const REPO = {".github/workflows/main.yml":"# Trusted build on main: immutable backend image by digest, staging deploy, smoke tests.\n# Merging to main is NOT an app-store release. Journey station 5 · Bug Hunt b3 · Drill 13\nname: main\n\non:\n  push:\n    branches: [main]\n\npermissions:\n  contents: read\n  packages: write        # push the API image to GHCR\n  id-token: write        # optional: cloud OIDC for the staging deploy (no long-lived cloud keys)\n\nconcurrency:\n  group: main-${{ github.ref }}\n  cancel-in-progress: false\n\njobs:\n  api-image:\n    runs-on: ubuntu-24.04\n    timeout-minutes: 30\n    outputs:\n      digest: ${{ steps.build.outputs.digest }}\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: docker/login-action@<pin-full-commit-sha> # v3.x\n        with:\n          registry: ghcr.io\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n      - id: build\n        uses: docker/build-push-action@<pin-full-commit-sha> # v6.x\n        with:\n          context: services/api\n          push: true\n          # One explicit reference, built and pushed. Tag = commit SHA, never :latest.\n          tags: ghcr.io/${{ github.repository_owner }}/routeready-api:${{ github.sha }}\n      - name: Record digest\n        run: |\n          echo \"image=ghcr.io/${{ github.repository_owner }}/routeready-api@${{ steps.build.outputs.digest }}\" | tee build-image.txt\n      - uses: actions/upload-artifact@<pin-full-commit-sha> # v4.x\n        with:\n          name: api-image-${{ github.sha }}\n          path: build-image.txt\n          retention-days: 90\n\n  staging:\n    needs: api-image\n    runs-on: ubuntu-24.04\n    timeout-minutes: 20\n    environment: staging\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - name: Deploy the verified digest (not a tag)\n        run: ./scripts/deploy-staging.sh \"ghcr.io/${{ github.repository_owner }}/routeready-api@${{ needs.api-image.outputs.digest }}\"\n      - name: Smoke tests against staging\n        run: ./scripts/smoke.sh \"${{ vars.STAGING_API_URL }}\"\n",".github/workflows/pr-ci.yml":"# PR CI: untrusted code. Read-only token, no secrets, no signing, no deploys.\n# Journey stations 3-4 · Drills 5-10 · Bug Hunt b1, b2, b10, b11\nname: pr-ci\n\non:\n  pull_request:\n  merge_group:            # merge queue support (drill 9)\n\npermissions:\n  contents: read          # least privilege; forks get no secrets on pull_request\n\nconcurrency:\n  group: pr-ci-${{ github.event.pull_request.number || github.ref }}\n  cancel-in-progress: true   # superseded PR runs are cancelled (never do this for releases)\n\njobs:\n  changes:\n    runs-on: ubuntu-24.04\n    timeout-minutes: 5\n    outputs:\n      ios: ${{ steps.f.outputs.ios }}\n      android: ${{ steps.f.outputs.android }}\n      api: ${{ steps.f.outputs.api }}\n      web: ${{ steps.f.outputs.web }}\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: dorny/paths-filter@<pin-full-commit-sha> # v3.x\n        id: f\n        with:\n          # Shared inputs (contracts, workflows, lanes, locks, scripts) trigger EVERY client.\n          filters: |\n            shared: &shared\n              - 'contracts/**'\n              - '.github/workflows/**'\n              - 'fastlane/**'\n              - 'Gemfile.lock'\n              - 'scripts/**'\n              - 'config/**'\n            ios:\n              - *shared\n              - 'apps/ios/**'\n            android:\n              - *shared\n              - 'apps/android/**'\n              - 'gradle/**'\n            api:\n              - *shared\n              - 'services/api/**'\n            web:\n              - *shared\n              - 'apps/dispatcher-web/**'\n\n  ios:\n    needs: changes\n    if: needs.changes.outputs.ios == 'true'\n    runs-on: macos-15            # pinned image; verify against docs/toolchain.md\n    timeout-minutes: 45\n    env:\n      XCODE_PATH: /Applications/Xcode_<VERIFY>.app   # from docs/toolchain.md\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - run: sudo xcode-select -s \"$XCODE_PATH\"\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with:\n          bundler-cache: true      # keyed on Gemfile.lock + Ruby version\n      - name: Record toolchain\n        run: ./scripts/print-toolchain.sh ios | tee build-toolchain-ios.txt\n      - name: Simulator build + tests (no signing)\n        run: bundle exec fastlane ios verify destination:\"$(./scripts/pick-simulator.sh)\"\n      - uses: actions/upload-artifact@<pin-full-commit-sha> # v4.x\n        if: always()\n        with:\n          name: ios-verify-${{ github.run_attempt }}\n          path: |\n            build/ios/**/*.xcresult\n            build-toolchain-ios.txt\n          retention-days: 14\n\n  android:\n    needs: changes\n    if: needs.changes.outputs.android == 'true'\n    runs-on: ubuntu-24.04\n    timeout-minutes: 40\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: actions/setup-java@<pin-full-commit-sha> # v4.x\n        with:\n          distribution: temurin\n          java-version: \"<VERIFY>\"   # must match the AGP requirement in docs/toolchain.md (drill 6)\n      - uses: gradle/actions/wrapper-validation@<pin-full-commit-sha> # v4.x — rejects a tampered gradle-wrapper.jar\n      - uses: gradle/actions/setup-gradle@<pin-full-commit-sha> # v4.x — cache keyed on wrapper, lock and build files (drill 7)\n        with:\n          cache-read-only: true    # PRs read caches; only trusted main writes them\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with:\n          bundler-cache: true\n      - run: ./scripts/print-toolchain.sh android | tee build-toolchain-android.txt\n      - run: bundle exec fastlane android verify\n      - uses: actions/upload-artifact@<pin-full-commit-sha> # v4.x\n        if: always()\n        with:\n          name: android-verify-${{ github.run_attempt }}\n          path: |\n            apps/android/app/build/reports/**\n            build-toolchain-android.txt\n          retention-days: 14\n\n  api:\n    needs: changes\n    if: needs.changes.outputs.api == 'true'\n    runs-on: ubuntu-24.04\n    timeout-minutes: 25\n    services:\n      postgres:\n        image: postgres:<VERIFY>\n        env:\n          POSTGRES_PASSWORD: lab-only-not-a-secret\n          POSTGRES_DB: routeready\n        ports: [\"5432:5432\"]\n        options: >-\n          --health-cmd \"pg_isready -U postgres\" --health-interval 5s --health-timeout 5s --health-retries 10\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n        with:\n          fetch-depth: 0           # contract check diffs against the merge base\n      - uses: actions/setup-java@<pin-full-commit-sha> # v4.x\n        with:\n          distribution: temurin\n          java-version: \"<VERIFY>\"\n      - name: Contract compatibility (previous + current clients)\n        run: ./scripts/contract-check.sh \"origin/${{ github.base_ref || 'main' }}\"\n      - name: Unit + integration tests\n        run: ./services/api/gradlew -p services/api test integrationTest\n        env:\n          DATABASE_URL: jdbc:postgresql://localhost:5432/routeready\n\n  web:\n    needs: changes\n    if: needs.changes.outputs.web == 'true'\n    runs-on: ubuntu-24.04\n    timeout-minutes: 15\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: actions/setup-node@<pin-full-commit-sha> # v4.x\n        with:\n          node-version-file: apps/dispatcher-web/.nvmrc\n          cache: npm\n          cache-dependency-path: apps/dispatcher-web/package-lock.json\n      - run: npm ci && npm test\n        working-directory: apps/dispatcher-web\n\n  # The ONLY required status check. Runs always; fails if anything that applied failed or was cancelled.\n  ci-gate:\n    if: always()\n    needs: [changes, ios, android, api, web]\n    runs-on: ubuntu-24.04\n    timeout-minutes: 5\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - run: ./scripts/gate.sh\n        env:\n          NEEDS_JSON: ${{ toJSON(needs) }}\n",".github/workflows/promote.yml":"# Production promotion: approval gate, promote the existing candidate, never recompile.\n# Journey stations 11-13 · Drill 15\nname: promote\n\non:\n  workflow_dispatch:\n    inputs:\n      platform:\n        type: choice\n        options: [ios, android]\n      build_number:\n        description: \"Existing build number / versionCode to promote\"\n        required: true\n      rollout:\n        description: \"Android staged rollout fraction (e.g. 0.1). iOS uses Apple's phased release.\"\n        default: \"0.1\"\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: promote-${{ inputs.platform }}-routeready\n  cancel-in-progress: false\n\njobs:\n  promote:\n    runs-on: ${{ inputs.platform == 'ios' && 'macos-15' || 'ubuntu-24.04' }}\n    timeout-minutes: 30\n    environment: production         # required reviewers configured on this environment\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with: { bundler-cache: true }\n      - name: Release preflight (candidate, compatibility evidence, approvals)\n        run: ./scripts/release-preflight.sh promote \"${{ inputs.platform }}\" \"${{ inputs.build_number }}\"\n      - name: Promote\n        env:\n          ASC_KEY_ID: ${{ secrets.ASC_KEY_ID }}\n          ASC_ISSUER_ID: ${{ secrets.ASC_ISSUER_ID }}\n          ASC_KEY_P8_BASE64: ${{ secrets.ASC_KEY_P8_BASE64 }}\n          PLAY_JSON_KEY: ${{ secrets.PLAY_JSON_KEY }}\n        run: bundle exec fastlane ${{ inputs.platform }} promote build_number:${{ inputs.build_number }} rollout:${{ inputs.rollout }}\n",".github/workflows/release-android.yml":"# Explicit Android beta release to the Play internal track.\n# Journey stations 7-10 · Drills 3, 4\nname: release-android\n\non:\n  workflow_dispatch:\n    inputs:\n      upload:\n        description: \"Upload to the internal track (off = package and validate only)\"\n        type: boolean\n        default: false\n\npermissions:\n  contents: write\n\nconcurrency:\n  group: release-android-routeready\n  cancel-in-progress: false\n\njobs:\n  package:\n    if: github.ref == 'refs/heads/main'\n    runs-on: ubuntu-24.04\n    timeout-minutes: 45\n    environment: release-android\n    outputs:\n      version_code: ${{ steps.alloc.outputs.number }}\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: actions/setup-java@<pin-full-commit-sha> # v4.x\n        with: { distribution: temurin, java-version: \"<VERIFY>\" }\n      - uses: gradle/actions/setup-gradle@<pin-full-commit-sha> # v4.x\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with: { bundler-cache: true }\n      - id: alloc\n        run: echo \"number=$(./scripts/allocate-build-number.sh android org.routeready.parent \"$GITHUB_SHA\")\" >> \"$GITHUB_OUTPUT\"\n      - name: Decode upload keystore to a temp file\n        env:\n          UPLOAD_KEYSTORE_BASE64: ${{ secrets.UPLOAD_KEYSTORE_BASE64 }}\n        run: |\n          umask 077\n          echo \"$UPLOAD_KEYSTORE_BASE64\" | base64 --decode > \"$RUNNER_TEMP/upload.jks\"\n          echo \"ROUTEREADY_UPLOAD_KEYSTORE=$RUNNER_TEMP/upload.jks\" >> \"$GITHUB_ENV\"\n      - name: Package signed AAB + mapping (fingerprint preflight blocks the wrong key)\n        env:\n          ROUTEREADY_UPLOAD_STORE_PASSWORD: ${{ secrets.UPLOAD_STORE_PASSWORD }}\n          ROUTEREADY_UPLOAD_KEY_ALIAS: ${{ secrets.UPLOAD_KEY_ALIAS }}\n          ROUTEREADY_UPLOAD_KEY_PASSWORD: ${{ secrets.UPLOAD_KEY_PASSWORD }}\n          EXPECTED_UPLOAD_CERT_SHA256: ${{ vars.EXPECTED_UPLOAD_CERT_SHA256 }}\n        run: bundle exec fastlane android package version_code:${{ steps.alloc.outputs.number }}\n      - uses: actions/upload-artifact@<pin-full-commit-sha> # v4.x\n        with:\n          name: android-release-${{ steps.alloc.outputs.number }}\n          path: |\n            apps/android/app/build/outputs/bundle/release/app-release.aab\n            apps/android/app/build/outputs/mapping/release/mapping.txt\n            evidence/release-manifest.json\n          retention-days: 90\n      - name: Delete keystore\n        if: always()\n        run: rm -f \"$RUNNER_TEMP/upload.jks\"\n\n  beta:\n    needs: package\n    if: inputs.upload\n    runs-on: ubuntu-24.04\n    timeout-minutes: 20\n    environment: release-android\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with: { bundler-cache: true }\n      - uses: actions/download-artifact@<pin-full-commit-sha> # v4.x\n        with:\n          name: android-release-${{ needs.package.outputs.version_code }}\n          path: build/android\n      - name: Upload the EXISTING AAB to the internal track\n        env:\n          PLAY_JSON_KEY: ${{ secrets.PLAY_JSON_KEY }}\n        run: bundle exec fastlane android beta aab:build/android/app/build/outputs/bundle/release/app-release.aab manifest:build/android/evidence/release-manifest.json\n",".github/workflows/release-ios.yml":"# Explicit iOS beta release. Separate package and beta jobs so a failed upload can be\n# re-run WITHOUT rebuilding. Journey stations 7-10 · Bug Hunt b5, b6 · Drills 1, 2, 4, 15\nname: release-ios\n\non:\n  workflow_dispatch:\n    inputs:\n      upload:\n        description: \"Upload to TestFlight (off = package and validate only)\"\n        type: boolean\n        default: false\n\npermissions:\n  contents: write        # allocator commits to the build-numbers branch\n  \nconcurrency:\n  group: release-ios-routeready      # one per app/platform\n  cancel-in-progress: false          # never kill an upload mid-flight\n\njobs:\n  package:\n    if: github.ref == 'refs/heads/main'\n    runs-on: macos-15\n    timeout-minutes: 60\n    environment: release-ios         # protected environment holds signing secrets\n    outputs:\n      build_number: ${{ steps.alloc.outputs.number }}\n    env:\n      XCODE_PATH: /Applications/Xcode_<VERIFY>.app\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - run: sudo xcode-select -s \"$XCODE_PATH\"\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with:\n          bundler-cache: true\n      - name: Allocate build number (durable, concurrency-safe)\n        id: alloc\n        run: echo \"number=$(./scripts/allocate-build-number.sh ios org.routeready.parent \"$GITHUB_SHA\")\" >> \"$GITHUB_OUTPUT\"\n      - name: Package (temp keychain, readonly match, signed IPA + dSYMs)\n        env:\n          MATCH_GIT_URL: ${{ secrets.MATCH_GIT_URL }}\n          MATCH_PASSWORD: ${{ secrets.MATCH_PASSWORD }}\n          MATCH_GIT_BASIC_AUTHORIZATION: ${{ secrets.MATCH_GIT_BASIC_AUTHORIZATION }}\n        run: bundle exec fastlane ios package build_number:${{ steps.alloc.outputs.number }}\n      - uses: actions/upload-artifact@<pin-full-commit-sha> # v4.x\n        with:\n          name: ios-release-${{ steps.alloc.outputs.number }}\n          path: |\n            build/ios/RouteReady.ipa\n            build/ios/RouteReady.app.dSYM.zip\n            evidence/release-manifest.json\n          retention-days: 90         # longer than your support window for symbols (drill 19)\n      - name: Remove temporary keychain\n        if: always()\n        run: bundle exec fastlane run delete_keychain name:fastlane_tmp_keychain || true\n\n  beta:\n    needs: package\n    if: inputs.upload\n    runs-on: macos-15\n    timeout-minutes: 30\n    environment: release-ios\n    steps:\n      - uses: actions/checkout@<pin-full-commit-sha> # v4.x\n      - uses: ruby/setup-ruby@<pin-full-commit-sha> # v1.x\n        with:\n          bundler-cache: true\n      - uses: actions/download-artifact@<pin-full-commit-sha> # v4.x\n        with:\n          name: ios-release-${{ needs.package.outputs.build_number }}\n          path: build/ios\n      - name: Upload the EXISTING IPA (verifies checksum first)\n        env:\n          ASC_KEY_ID: ${{ secrets.ASC_KEY_ID }}\n          ASC_ISSUER_ID: ${{ secrets.ASC_ISSUER_ID }}\n          ASC_KEY_P8_BASE64: ${{ secrets.ASC_KEY_P8_BASE64 }}\n        run: bundle exec fastlane ios beta ipa:build/ios/RouteReady.ipa manifest:build/ios/evidence/release-manifest.json\n",".gitignore":"# Signing material never enters git\n*.p12\n*.cer\n*.mobileprovision\n*.keystore\n*.jks\n*.p8\n.env\n.env.*\n!.env.example\nfastlane/report.xml\nfastlane/README.md\nbuild/\n**/build/\n.gradle/\nnode_modules/\nDerivedData/\n","Gemfile":"source \"https://rubygems.org\"\n\n# Exact versions live in Gemfile.lock (commit it). Upgrade through a reviewed toolchain PR.\ngem \"fastlane\"\n","README.md":"# routeready-mobile-devops (reference)\n\nReference repository for the **Signed & Shipped** Mobile DevOps training game and the *Mobile DevOps Portfolio and Interview Playbook*.\nIt shows what each stage of a mobile release pipeline looks like as real files: GitHub Actions workflows, Fastlane lanes, release scripts, contracts, docs and drill write-ups.\n\n**What this is:** a starting point you clone, read and fill in.\n**What this is not:** a finished app or a verified pipeline. App code isn't included, tool versions are `<VERIFY>` placeholders, and action SHAs are `<pin-full-commit-sha>` placeholders. Nothing here has been run against real store accounts. See [docs/progress.md](docs/progress.md).\n\nRouteReady (SwiftUI + Kotlin + Spring Boot) is the main lab. Key StayReady (React Native + FastAPI) snippets live in `stayready/` for the tenant, idempotency and OTA drills.\n\n## Quick start\n1. Clone it: `git clone <your-repo-url> routeready-mobile-devops`\n2. Fill [docs/toolchain.md](docs/toolchain.md) from official compatibility docs, then replace every `<VERIFY>` and pin every action to a full commit SHA.\n3. Create the allocator branch: `git switch --orphan build-numbers && echo '{}' > allocations.json && git add . && git commit -m init && git push -u origin build-numbers`\n4. Set up branch protection and environments: [docs/branch-protection.md](docs/branch-protection.md).\n5. Add your app projects under `apps/ios` and `apps/android`, then run `bundle exec fastlane ios verify destination:\"$(./scripts/pick-simulator.sh)\"`.\n6. Track every milestone as IMPLEMENTED / VERIFIED / SIMULATED / BLOCKED in [docs/progress.md](docs/progress.md).\n\n## The Journey, file by file (code → customer)\n| # | Station | Phase | Reference files |\n|---|---|---|---|\n| 1 | Pin the toolchain | Build | [docs/toolchain.md](docs/toolchain.md)<br>[scripts/print-toolchain.sh](scripts/print-toolchain.sh)<br>[scripts/pick-simulator.sh](scripts/pick-simulator.sh)<br>[Gemfile](Gemfile) |\n| 2 | Branch small, hide unfinished work | Build | [docs/adr/0001-trunk-based-development.md](docs/adr/0001-trunk-based-development.md)<br>[config/feature-flags.json](config/feature-flags.json)<br>[docs/branch-protection.md](docs/branch-protection.md) |\n| 3 | Pull request CI (untrusted) | Build | [.github/workflows/pr-ci.yml](.github/workflows/pr-ci.yml)<br>[fastlane/Fastfile](fastlane/Fastfile) |\n| 4 | Required check, review, merge | Build | [scripts/gate.sh](scripts/gate.sh)<br>[.github/workflows/pr-ci.yml](.github/workflows/pr-ci.yml)<br>[docs/branch-protection.md](docs/branch-protection.md) |\n| 5 | Trusted main build + staging | Integrate | [.github/workflows/main.yml](.github/workflows/main.yml)<br>[scripts/deploy-staging.sh](scripts/deploy-staging.sh)<br>[scripts/smoke.sh](scripts/smoke.sh)<br>[infra/docker-compose.yml](infra/docker-compose.yml) |\n| 6 | Backend first, additive only | Integrate | [contracts/openapi.yaml](contracts/openapi.yaml)<br>[contracts/fixtures/v1.3/route-status.json](contracts/fixtures/v1.3/route-status.json)<br>[scripts/contract-check.sh](scripts/contract-check.sh)<br>[services/api/db/migrations/README.md](services/api/db/migrations/README.md) |\n| 7 | Release preflight + build number | Package | [scripts/release-preflight.sh](scripts/release-preflight.sh)<br>[scripts/allocate-build-number.sh](scripts/allocate-build-number.sh)<br>[config/apps.json](config/apps.json) |\n| 8 | Sign and package | Package | [fastlane/Fastfile](fastlane/Fastfile)<br>[fastlane/Matchfile](fastlane/Matchfile)<br>[scripts/signing-preflight-ios.sh](scripts/signing-preflight-ios.sh)<br>[apps/android/app/signing.gradle.kts](apps/android/app/signing.gradle.kts)<br>[scripts/verify-upload-cert.sh](scripts/verify-upload-cert.sh) |\n| 9 | Release manifest + artifacts | Package | [scripts/write-manifest.sh](scripts/write-manifest.sh)<br>[evidence/release-manifest.schema.json](evidence/release-manifest.schema.json)<br>[scripts/verify-manifest.sh](scripts/verify-manifest.sh) |\n| 10 | Beta upload | Release | [.github/workflows/release-ios.yml](.github/workflows/release-ios.yml)<br>[.github/workflows/release-android.yml](.github/workflows/release-android.yml)<br>[scripts/record-state.sh](scripts/record-state.sh) |\n| 11 | Validate the production candidate | Release | [scripts/preflight-env.sh](scripts/preflight-env.sh)<br>[config/apps.json](config/apps.json) |\n| 12 | Approval gate + store review | Release | [.github/workflows/promote.yml](.github/workflows/promote.yml)<br>[docs/release-checklist.md](docs/release-checklist.md) |\n| 13 | Phased / staged rollout + feature cohorts | Release | [docs/rollout.md](docs/rollout.md)<br>[config/feature-flags.json](config/feature-flags.json) |\n| 14 | Observe with the right symbols | Operate | [docs/observability.md](docs/observability.md)<br>[scripts/upload-symbols.sh](scripts/upload-symbols.sh) |\n| 15 | Respond: contain, fix, verify | Operate | [docs/incident-runbook.md](docs/incident-runbook.md)<br>[docs/rollout.md](docs/rollout.md) |\n| 16 | Write it up, prevent it | Operate | [drills/_template/incident.md](drills/_template/incident.md)<br>[evidence/README.md](evidence/README.md)<br>[docs/progress.md](docs/progress.md) |\n\n## Drills\n| # | Drill | Lab | Priority |\n|---|---|---|---|\n| 1 | [iOS provisioning mismatch](drills/01-ios-provisioning-mismatch/README.md) | RouteReady | ★ |\n| 2 | [Locked CI keychain](drills/02-locked-ci-keychain/README.md) | RouteReady |  |\n| 3 | [Wrong Android upload key](drills/03-wrong-android-upload-key/README.md) | Either | ★ |\n| 4 | [Duplicate build numbers](drills/04-duplicate-build-numbers/README.md) | Either | ★ |\n| 5 | [Runner/toolchain drift](drills/05-runner-toolchain-drift/README.md) | RouteReady |  |\n| 6 | [Gradle/JDK incompatibility](drills/06-gradle-jdk-incompatibility/README.md) | Either |  |\n| 7 | [Poisoned or stale dependency cache](drills/07-poisoned-or-stale-dependency-cache/README.md) | Either |  |\n| 8 | [Flaky UI test](drills/08-flaky-ui-test/README.md) | RouteReady |  |\n| 9 | [Required check stuck pending](drills/09-required-check-stuck-pending/README.md) | Either |  |\n| 10 | [Secret exposure through a PR](drills/10-secret-exposure-through-a-pr/README.md) | Either | ★ |\n| 11 | [API breaks an installed client](drills/11-api-breaks-an-installed-client/README.md) | RouteReady | ★ |\n| 12 | [Stale or out-of-order GPS data](drills/12-stale-or-out-of-order-gps-data/README.md) | RouteReady |  |\n| 13 | [Backend readiness and bad rollout](drills/13-backend-readiness-and-bad-rollout/README.md) | RouteReady |  |\n| 14 | [Destructive database migration](drills/14-destructive-database-migration/README.md) | Either |  |\n| 15 | [Store processing or review delay](drills/15-store-processing-or-review-delay/README.md) | Either |  |\n| 16 | [Crash increase after rollout](drills/16-crash-increase-after-rollout/README.md) | Either | ★ |\n| 17 | [Wrong environment or tenant config](drills/17-wrong-environment-or-tenant-config/README.md) | StayReady |  |\n| 18 | [Offline duplicate service request](drills/18-offline-duplicate-service-request/README.md) | StayReady |  |\n| 19 | [Crash report lacks usable symbols](drills/19-crash-report-lacks-usable-symbols/README.md) | StayReady |  |\n| 20 | [Incompatible OTA update / unsafe AI change](drills/20-incompatible-ota-update-unsafe-ai-change/README.md) | StayReady |  |\n\n## Secrets and settings (names only)\n| Name | Where | Used by |\n|---|---|---|\n| `MATCH_GIT_URL`, `MATCH_PASSWORD`, `MATCH_GIT_BASIC_AUTHORIZATION` | env `release-ios` | package lane (readonly match) |\n| `ASC_KEY_ID`, `ASC_ISSUER_ID`, `ASC_KEY_P8_BASE64` | env `release-ios`, `production` | beta + promote |\n| `UPLOAD_KEYSTORE_BASE64`, `UPLOAD_STORE_PASSWORD`, `UPLOAD_KEY_ALIAS`, `UPLOAD_KEY_PASSWORD` | env `release-android` | package lane |\n| `EXPECTED_UPLOAD_CERT_SHA256` (variable) | env `release-android` | upload-key preflight |\n| `PLAY_JSON_KEY` | env `release-android`, `production` | beta + promote |\n\nPR workflows never see any of these.\n\n## Using Claude here\nAPI key or workload identity federation? See [docs/claude-api-auth.md](docs/claude-api-auth.md).\n","apps/android/README.md":"# apps/android (Kotlin)\n\nNot included in this reference. Create the Gradle project here with the same four screens as iOS.\nCommit the Gradle wrapper and its checksum. Merge `app/signing.gradle.kts` into `app/build.gradle.kts`.\n\nEmulator networking: the emulator reaches the host machine at `10.0.2.2`, not `localhost`.\n","apps/android/app/signing.gradle.kts":"// Reference snippet for apps/android/app/build.gradle.kts (drill 3).\n// Release builds are signed with the UPLOAD key. Google re-signs with the app signing key (Play App Signing).\n// Values come from the environment of a trusted release job — never from committed files.\nandroid {\n    signingConfigs {\n        create(\"upload\") {\n            val ks = System.getenv(\"ROUTEREADY_UPLOAD_KEYSTORE\")\n            if (ks != null) {\n                storeFile = file(ks)\n                storePassword = System.getenv(\"ROUTEREADY_UPLOAD_STORE_PASSWORD\")\n                keyAlias = System.getenv(\"ROUTEREADY_UPLOAD_KEY_ALIAS\")\n                keyPassword = System.getenv(\"ROUTEREADY_UPLOAD_KEY_PASSWORD\")\n            }\n        }\n    }\n    defaultConfig {\n        // Build number comes from the allocator, passed as a Gradle property by the package lane.\n        versionCode = (project.findProperty(\"routereadyVersionCode\") as String?)?.toInt() ?: 1\n    }\n    buildTypes {\n        getByName(\"release\") {\n            isMinifyEnabled = true            // keep mapping.txt for crash symbolication\n            signingConfig = signingConfigs.getByName(\"upload\")\n        }\n    }\n}\n","apps/ios/README.md":"# apps/ios (SwiftUI)\n\nNot included in this reference. Create the Xcode project here (`RouteReady.xcodeproj`, scheme `RouteReady`)\nwith four screens: demo sign-in, assigned route, bus status with observation time and stale indicator, service alerts.\n\nSimulator networking: the iOS simulator can reach the Mac's `localhost`. A physical device cannot;\nuse the Mac's LAN address or a tunnel, configured per build, never hardcoded.\n","config/apps.json":"{\n  \"marketing_version\": \"1.5.0\",\n  \"ios\": { \"application_id\": \"org.routeready.parent\" },\n  \"android\": { \"application_id\": \"org.routeready.parent\" },\n  \"environments\": {\n    \"staging\": { \"api_base_url\": \"https://staging-api.routeready.example\" },\n    \"production\": { \"api_base_url\": \"https://api.routeready.example\" }\n  }\n}\n","config/feature-flags.json":"{\n  \"defaults\": {\n    \"eta_confidence_enabled\": false\n  },\n  \"cohorts\": {\n    \"eta_confidence_enabled\": [\"beta-district-1\"]\n  },\n  \"notes\": \"Flags control exposure, never authorization. New behavior defaults OFF so a crash before flags load stays dark (drill 16).\"\n}\n","contracts/fixtures/v1.3/route-status.json":"{\n  \"_comment\": \"Recorded response shape the installed 1.3 client decodes. Must keep passing (drill 11).\",\n  \"route_id\": \"r-1\",\n  \"status\": \"DELAYED\",\n  \"delay_minutes\": 4,\n  \"observed_at\": \"2026-09-08T13:02:10Z\"\n}\n","contracts/fixtures/v1.5/route-status.json":"{\n  \"route_id\": \"r-1\",\n  \"status\": \"ON_TIME\",\n  \"delay_minutes\": 0,\n  \"observed_at\": \"2026-09-08T13:02:10Z\",\n  \"is_stale\": false,\n  \"eta_confidence\": 0.82\n}\n","contracts/openapi.yaml":"openapi: 3.0.3\ninfo:\n  title: RouteReady API (fictional portfolio lab)\n  version: v1\n  description: |\n    Additive changes only. Never rename, remove or change the type of a field\n    installed clients read. App marketing versions are independent of this contract.\npaths:\n  /api/v1/capabilities:\n    get:\n      summary: Features the server supports (clients adapt; never used for authorization)\n      responses:\n        \"200\":\n          description: ok\n          content:\n            application/json:\n              schema:\n                type: object\n                required: [contract]\n                properties:\n                  contract: { type: string, example: v1 }\n                  features: { type: array, items: { type: string }, example: [eta_confidence] }\n  /api/v1/routes:\n    get:\n      summary: Routes the caller is authorized to see\n      responses:\n        \"200\":\n          description: ok\n          content:\n            application/json:\n              schema: { type: array, items: { $ref: \"#/components/schemas/Route\" } }\n  /api/v1/routes/{id}/status:\n    get:\n      parameters: [{ name: id, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\":\n          description: ok\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/RouteStatus\" }\n        \"404\": { description: not found or not authorized }\n  /api/v1/telemetry:\n    post:\n      summary: Producer-authenticated GPS event ingestion (idempotent by event_id)\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: \"#/components/schemas/TelemetryEvent\" }\n      responses:\n        \"202\": { description: accepted (new or duplicate) }\n        \"409\": { description: older than current position; stored, not applied }\n  /api/v1/alerts:\n    get:\n      responses:\n        \"200\": { description: ok }\ncomponents:\n  schemas:\n    Route:\n      type: object\n      required: [route_id, name]\n      properties:\n        route_id: { type: string }\n        name: { type: string }\n    RouteStatus:\n      type: object\n      required: [route_id, status, observed_at]\n      properties:\n        route_id: { type: string }\n        status: { type: string, enum: [ON_TIME, DELAYED] }\n        delay_minutes: { type: integer }\n        observed_at: { type: string, format: date-time }\n        is_stale: { type: boolean, description: \"Added in contract rev 3. Additive.\" }\n        eta_confidence: { type: number, nullable: true, description: \"Optional. Behind eta_confidence_enabled.\" }\n    TelemetryEvent:\n      type: object\n      required: [event_id, bus_id, route_id, observed_at, sequence, boot_epoch, latitude, longitude]\n      properties:\n        event_id: { type: string }\n        bus_id: { type: string }\n        route_id: { type: string }\n        observed_at: { type: string, format: date-time }\n        sequence: { type: integer }\n        boot_epoch: { type: string, description: \"Changes when the producer reboots (drill 12)\" }\n        latitude: { type: number }\n        longitude: { type: number }\n","docs/adr/0001-trunk-based-development.md":"# ADR 0001: Trunk-based development with feature flags\n\n**Status:** accepted · **Context:** small team, mobile + backend in one repo.\n\n**Decision:** short-lived branches into protected `main`; unfinished behavior behind flags defaulting OFF; no permanent `develop` branch.\n\n**Consequences:** `main` is always releasable but never automatically released to stores. Releases are explicit workflow runs.\n","docs/adr/0002-github-actions-and-fastlane.md":"# ADR 0002: GitHub Actions for orchestration, Fastlane for mobile logic\n\n**Decision:** workflows stay thin (triggers, permissions, environments); build/sign/upload logic lives in Fastlane lanes and `scripts/` so it runs the same locally and could be ported to Jenkins.\n\n**Rejected:** App Center (Build/Test/Distribute retired), running every tool at once (Jenkins + GitLab + Xcode Cloud + EAS) while learning.\n","docs/branch-protection.md":"# Branch protection for `main`\n\n- Require pull request with 1 approving review.\n- Require status check **ci-gate** only (the aggregate job). Don't add individual path-filtered jobs as required.\n- Require branches to be up to date, or use a merge queue (the workflow listens to `merge_group`).\n- Disallow force pushes and deletions.\n- Environments: `release-ios`, `release-android` (deployment branch: main only), `production` (required reviewers).\n","docs/claude-api-auth.md":"# Using Claude from this lab: API key or workload identity federation?\n\n| Where the code runs | Use |\n|---|---|\n| The **Signed & Shipped** game artifact on claude.ai | Neither. The page asks Claude on the viewer's own Claude account; no key exists in the page. |\n| A browser page you host yourself | **Never** put an API key in browser JavaScript; anyone can read it. Call your own small backend instead. |\n| Your backend / a server you run | An API key from Claude Console stored in a secret manager, **or** workload identity federation if that server already gets OIDC tokens from a trusted issuer (cloud workload identity, Kubernetes). |\n| GitHub Actions (e.g. AI PR review in this repo) | **Workload identity federation**: register GitHub's OIDC issuer in Claude Console → Keys & access → Workload identity, then add a rule scoped to this repository (and branch/environment). No long-lived key to leak or rotate. |\n\nWhy federation for CI: it's the same idea as cloud OIDC in `main.yml`. The job proves *who it is* with a short-lived token instead of holding a password. Scope the rule tightly (one repo, protected branch or environment) so a fork PR can't use it.\n\nRemember the playbook rule: OIDC replaces long-lived cloud/API keys, not App Store Connect keys or signing keystores.\n\nCheck the current setup steps in the Claude docs (docs.claude.com) before wiring it up.\n","docs/incident-runbook.md":"# Incident runbook\n\n1. **Signal:** what alerted, when (relative time), which release/build.\n2. **Scope:** which platforms, versions, cohorts. Who's installed (old clients too).\n3. **Contain:** flag off · pause phased release / halt staged rollout · revert backend to a *compatible* digest.\n4. **Diagnose:** evidence first (manifest, logs, symbols). Write rejected hypotheses down.\n5. **Fix:** compatible backend fix, or replacement binary with a higher build number through the normal gates.\n6. **Verify:** against the actual failure, including the installed population.\n7. **Prevent:** a preflight, test or gate. Name an owner.\n8. **Write up:** `drills/_template/incident.md`. No invented minutes or money.\n","docs/observability.md":"# Observability\n\n- Structured logs: `request_id`, `app_version`, `build`, `environment`, redacted `route_id`/`tenant`.\n- Crash reporting (optional Sentry): upload the exact dSYMs / `mapping.txt` / source maps from the shipped build (`scripts/upload-symbols.sh`). Release = `marketing_version`, dist = build number.\n- Dashboards segment by release, OS, device and feature cohort. Show sample size.\n- Targets are **lab targets** (e.g. stale indicator after 60 s), not achieved results. Record hardware, workload and sample count with any measurement.\n","docs/progress.md":"# Progress\n\n| Milestone | Status | Evidence |\n|---|---|---|\n| Toolchain recorded | NOT STARTED | docs/toolchain.md |\n| Local vertical slice (event → API → both apps) | NOT STARTED | |\n| PR CI with aggregate gate | NOT STARTED | |\n| Failing test + breaking contract blocked | NOT STARTED | |\n| iOS package lane (signed) | BLOCKED: needs Apple Developer account | |\n| iOS simulator verify | NOT STARTED | |\n| Android signed AAB | NOT STARTED | |\n| Build-number allocator race test | NOT STARTED | |\n| Beta upload (TestFlight / internal) | BLOCKED: needs store accounts | |\n| Observability + symbols | NOT STARTED | |\n| Priority drills 1, 3, 4, 10, 11, 16 | NOT STARTED | drills/ |\n\nStatuses: IMPLEMENTED · VERIFIED · SIMULATED · BLOCKED. A Fastfile on disk is not a signed build.\n","docs/release-checklist.md":"# Release checklist\n\n- [ ] Backend additive change deployed by digest; previous + current client contract tests green\n- [ ] New behavior behind a flag, default OFF\n- [ ] `release preflight` passed (trusted commit, app ID, build number, environment, settings)\n- [ ] Build number allocated (no reuse), signed artifact checksummed into the manifest\n- [ ] Symbols retained (dSYM / mapping / source maps) with retention > support window\n- [ ] Uploaded → processing → testers available (each recorded separately)\n- [ ] Production candidate's compiled config points at production\n- [ ] Approval recorded on the `production` environment\n- [ ] Rollout plan: phased (iOS) / staged % (Android), flag cohort, dashboards ready\n- [ ] Runbook owner on call\n","docs/rollout.md":"# Rollout levers\n\n| Lever | Controls | Reaches installed apps? |\n|---|---|---|\n| Apple phased release | Automatic updates on Apple's fixed 7-day schedule; pausable; manual updates still allowed | No |\n| Google Play staged rollout | % of users offered the update; you choose, raise, or halt | No |\n| Feature flag / cohort | Who sees new behavior | **Yes** (if flags load before the code path) |\n| Backend fix or revert to a compatible digest | Server behavior for every client | **Yes** |\n| Replacement binary (higher build number) | The fix itself | After users update |\n\n\"Rollback\" must name which lever. You can't uninstall a binary from a phone.\n","docs/toolchain.md":"# Toolchain record\n\nFill every `<VERIFY>` from official compatibility docs AND what the runner image actually has.\nRecord the date. Upgrade only through a reviewed PR that updates this file and the workflows together.\n\nVerified on: `<YYYY-MM-DD>` by `<you>`\n\n| Tool | Version | Source checked |\n|---|---|---|\n| macOS runner image | `macos-15` (confirm in runner-images) | actions/runner-images |\n| Xcode | `<VERIFY>` | runner image README |\n| iOS simulator runtime | `<VERIFY>` | `xcrun simctl list runtimes available` |\n| Swift | `<VERIFY>` | `swift --version` |\n| Android Gradle Plugin | `<VERIFY>` | AGP release notes (minimum JDK + Gradle) |\n| Gradle wrapper | `<VERIFY>` + checksum | `gradle-wrapper.properties` |\n| JDK | `<VERIFY>` (Temurin) | AGP requirement |\n| Kotlin | `<VERIFY>` | AGP/Kotlin compatibility table |\n| Android SDK / build tools | `<VERIFY>` | `sdkmanager --list_installed` |\n| Ruby / Bundler / Fastlane | `<VERIFY>` | `Gemfile.lock` |\n| Node / React Native (StayReady) | `<VERIFY>` | RN compatibility docs |\n| Python (StayReady API) | `<VERIFY>` | |\n| Java (RouteReady API) | `<VERIFY>` | |\n| Third-party actions | full commit SHAs | each action's release page |\n\nCommands to capture as evidence: `./scripts/print-toolchain.sh`, `xcodebuild -showdestinations -scheme RouteReady`, `xcrun simctl list devices available`.\n","drills/01-ios-provisioning-mismatch/README.md":"# Drill 1: iOS provisioning mismatch\n\n**Lab:** RouteReady · **Area:** Signing · **Interview priority**\n\n> Like you're 10: Your concert ticket is for Seat 12, but you're trying to sit in Seat 14. Practicing at home (simulator) never checked your ticket.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, configured the release with an entitlement missing from its provisioning profile. Use test assets or preflight fixtures. Never revoke real certificates.\n\n## 2. Expected symptom\nPR CI on the simulator is green. The explicit release run fails during export.\n\nExample (redacted) output, release-ios #212 · fastlane ios package:\n```\n[13:02:04] gym: ▸ Archive Succeeded\n[13:02:11] gym: Exporting archive with export_method app-store\nerror: exportArchive: Provisioning profile \"RouteReady AppStore\" doesn't include the com.apple.developer.associated-domains entitlement.\nerror: exportArchive: Profile doesn't match the entitlements file's value for the application-identifier entitlement.\n** EXPORT FAILED **\n[13:02:12] Error building the application - see the log above\n```\n\n## 3. Diagnose\n- Leading hypothesis: The profile doesn't cover the app's bundle ID/entitlements, a distribution-signing mismatch the simulator never exercised\n- Next command: xcodebuild -showBuildSettings | grep -E 'PRODUCT_BUNDLE_IDENTIFIER|CODE_SIGN_ENTITLEMENTS|DEVELOPMENT_TEAM' and security cms -D -i the .mobileprovision\n\n## 4. Contain and fix\nStop the release; add the capability to the App ID and regenerate the profile through the authorized provisioning process; CI stays read-only\n\n## 5. Verify\nA preflight fixture with the wrong mapping fails fast, and a real archive/export passes with valid assets, recorded in the manifest\n\n## 6. Complication to rehearse\nThe admin regenerated the profile. CI still fails and the log shows the OLD profile UUID. → A stale profile is cached on the runner or in a restored cache; make match fetch fresh and scope or clear only that cache\n\n## 7. Senior follow-up\n**Why does successful simulator testing say nothing about distribution signing?**\n\n<details><summary>Strong answer</summary>\n\nSimulator builds aren't signed with your distribution certificate, don't embed an App Store profile, and never go through export. Bundle ID, team, entitlements and profile are only validated at archive/export, so the simulator can't catch this class of failure.\n</details>\n\n## Reference files\n- [scripts/signing-preflight-ios.sh](../../scripts/signing-preflight-ios.sh)\n- [fastlane/Matchfile](../../fastlane/Matchfile)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/02-locked-ci-keychain/README.md":"# Drill 2: Locked CI keychain\n\n**Lab:** RouteReady · **Area:** Signing\n\n> Like you're 10: The seal stamp is in a locked drawer and nobody's there to type the code, so the job just stands there waiting.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, skipped CI keychain setup on a disposable runner. Use test assets or preflight fixtures. Never revoke real certificates.\n\n## 2. Expected symptom\ncodesign hangs until the job times out, or fails with 'errSecInternalComponent'.\n\nExample (redacted) output, release-ios #219 · fastlane ios package:\n```\n[09:14:02] gym: /usr/bin/codesign --force --sign ●●●●●●●● --entitlements …\n[09:14:02] … no output …\n[09:44:02] Error: The operation was canceled. (timeout-minutes: 30)\n--- retry on a different runner ---\nWarning: unable to build chain to self-signed root for signer\nRouteReady.app: errSecInternalComponent\n```\n\n## 3. Diagnose\n- Leading hypothesis: codesign can't access the private key non-interactively: the keychain is locked or the key partition list isn't set\n- Next command: security find-identity -v -p codesigning and security list-keychains -d user, to separate 'identity missing' from 'access denied'\n\n## 4. Contain and fix\nRestore setup_ci (temporary unlocked keychain set as default), match readonly into it, and delete_keychain in a cleanup that always runs\n\n## 5. Verify\nTwo fresh runners package without prompts, and a post-job check shows no temp keychain or .p12 left behind\n\n## 6. Complication to rehearse\nOn a self-hosted Mac, a job crashed mid-way. The next job on that runner finds a leftover keychain with the signing identity. → Cleanup runs in an always()/ensure block, keychain names are unique per run, and a sweep step removes stragglers\n\n## 7. Senior follow-up\n**Why not leave a shared runner's keychain permanently unlocked?**\n\n<details><summary>Strong answer</summary>\n\nAny job that lands on that runner, including other projects or untrusted code, could sign arbitrary binaries with your identity. Keys sit on disk indefinitely, isolation and audit break, and you'd never know who used them.\n</details>\n\n## Reference files\n- [.github/workflows/release-ios.yml](../../.github/workflows/release-ios.yml)\n- [fastlane/Fastfile](../../fastlane/Fastfile)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/03-wrong-android-upload-key/README.md":"# Drill 3: Wrong Android upload key\n\n**Lab:** Either · **Area:** Signing · **Interview priority**\n\n> Like you're 10: You signed the permission slip with your friend's name. The office knows your signature and says no.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, pointed the package lane at a different test keystore. Use test assets or preflight fixtures. Never revoke real certificates.\n\n## 2. Expected symptom\nThe Gradle build succeeds, but Play rejects the upload.\n\nExample (redacted) output, release-android #88 · fastlane android beta:\n```\n> Task :app:bundleRelease\nBUILD SUCCESSFUL in 3m 12s\n[upload_to_play_store] Uploading app-release.aab to track 'internal'…\nGoogle Api Error: Invalid request - The Android App Bundle was signed with the wrong key.\n  Found: SHA1: 3B:●●:●●:…:91\n  Expected: SHA1: A7:●●:●●:…:0C\n```\n\n## 3. Diagnose\n- Leading hypothesis: The AAB was signed with a key that isn't the registered upload key\n- Next command: keytool -printcert -jarfile app-release.aab, and compare to the upload certificate in Play Console (not the app signing cert)\n\n## 4. Contain and fix\nPoint the lane back at the intended upload keystore from the protected secret; if truly lost, use Play's upload key reset\n\n## 5. Verify\nA fingerprint preflight blocks the wrong key before upload; a fixture test with the wrong test keystore fails\n\n## 6. Complication to rehearse\nA teammate suggests committing the keystore to the repo 'so this never happens again'. → No. Keep it in a secret manager/protected environment, decode to a temp file per job, delete it in an always step; the preflight catches mismatches\n\n## 7. Senior follow-up\n**Why shouldn't an upload-key incident trigger app signing key replacement?**\n\n<details><summary>Strong answer</summary>\n\nThe app signing key is held by Google and is what installed apps verify updates against. The upload key only authenticates your uploads to Play. An upload key reset doesn't affect users at all, while an app signing key upgrade is heavyweight and unnecessary here.\n</details>\n\n## Reference files\n- [scripts/verify-upload-cert.sh](../../scripts/verify-upload-cert.sh)\n- [apps/android/app/signing.gradle.kts](../../apps/android/app/signing.gradle.kts)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/04-duplicate-build-numbers/README.md":"# Drill 4: Duplicate build numbers\n\n**Lab:** Either · **Area:** Release · **Interview priority**\n\n> Like you're 10: Two deli machines both printed ticket 57. Only one customer gets served; the other is confused.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, launched two release jobs at the same time against the same counter.\n\n## 2. Expected symptom\nOne upload succeeds, the other is rejected, and a retry creates an ambiguous artifact.\n\nExample (redacted) output, release-ios #418 / #419:\n```\nrelease-ios #418  sha=9f2c4e1  build_number=57  upload ✔\nrelease-ios #419  sha=b71a0d3  build_number=57\n[upload_to_testflight] ERROR ITMS-90189: Redundant Binary Upload.\n  You've already uploaded a build with build version '57' for version number '1.4.0'.\n[retry] gym: Archiving RouteReady…   # rebuilt on retry\n```\n\n## 3. Diagnose\n- Leading hypothesis: Two jobs read the same counter at once; allocation isn't serialized or durable\n- Next command: Compare both manifests (SHA, build number, artifact SHA-256), the allocator's state/log and the store's build history\n\n## 4. Contain and fix\nSerialize allocation per app/platform with an atomic store; persist the reservation with the SHA; retries reuse the original artifact and checksum\n\n## 5. Verify\nLaunch two parallel release jobs in a sandbox: distinct numbers; an upload retry references the same checksum without rebuilding\n\n## 6. Complication to rehearse\nThe repo moves to a new GitHub org. Run counters reset to 1. → The allocator is external and seeded from the store's latest build number; it never goes backward\n\n## 7. Senior follow-up\n**What changes when moving to a new CI repository?**\n\n<details><summary>Strong answer</summary>\n\nRun counters reset, secrets and environments must be recreated, OIDC trust conditions reference the repo name, and caches start cold. The allocator must live outside the CI repo and be seeded from the store's highest build number. Also watch Android's versionCode ceiling.\n</details>\n\n## Reference files\n- [scripts/allocate-build-number.sh](../../scripts/allocate-build-number.sh)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/05-runner-toolchain-drift/README.md":"# Drill 5: Runner/toolchain drift\n\n**Lab:** RouteReady · **Area:** CI\n\n> Like you're 10: Your recipe says 'bake in Oven #3', but the school replaced the ovens over the weekend.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, changed the runner image so the expected simulator disappeared.\n\n## 2. Expected symptom\nxcodebuild says 'Unable to find a destination' or reports an SDK incompatibility.\n\nExample (redacted) output, pr-ci #1042 · ios-verify:\n```\n$ xcodebuild test -scheme RouteReady -destination 'platform=iOS Simulator,name=iPhone 15,OS=17.0'\nxcodebuild: error: Unable to find a destination matching the provided destination specifier:\n    { platform:iOS Simulator, OS:17.0, name:iPhone 15 }\n  Available destinations for the \"RouteReady\" scheme:\n    { platform:iOS Simulator, arch:arm64, id:●●●●, OS:26.0, name:iPhone 17 }\n```\n\n## 3. Diagnose\n- Leading hypothesis: The runner image/Xcode changed and the hardcoded destination no longer exists\n- Next command: xcodebuild -version; xcode-select -p; xcodebuild -showdestinations; xcrun simctl list devices available, and compare to docs/toolchain.md\n\n## 4. Contain and fix\nPin the runner image and Xcode, pick a destination from the detected list, upgrade through a reviewed toolchain PR\n\n## 5. Verify\nA fresh-runner matrix passes for the declared images and the job prints its toolchain into evidence\n\n## 6. Complication to rehearse\nThe image you pinned is announced for retirement in six weeks. → Open a toolchain PR now that runs the new image in a non-blocking matrix job, compare results, then switch the required check\n\n## 7. Senior follow-up\n**How do you upgrade before a hosted image is retired?**\n\n<details><summary>Strong answer</summary>\n\nWatch the runner-images announcements, add the candidate image to the nightly matrix, update toolchain.md with verified versions, measure build time and failures, then flip the required job through a reviewed PR.\n</details>\n\n## Reference files\n- [scripts/pick-simulator.sh](../../scripts/pick-simulator.sh)\n- [docs/toolchain.md](../../docs/toolchain.md)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/06-gradle-jdk-incompatibility/README.md":"# Drill 6: Gradle/JDK incompatibility\n\n**Lab:** Either · **Area:** CI\n\n> Like you're 10: The game cartridge needs a newer console than the one plugged in.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, changed the JDK without changing the pinned Android build tools.\n\n## 2. Expected symptom\n'Unsupported class file major version' or the Android Gradle Plugin refuses to apply.\n\nExample (redacted) output, pr-ci #1051 · android-verify:\n```\nFAILURE: Build failed with an exception.\n* What went wrong:\nAn exception occurred applying plugin request [id: 'com.android.application']\n> Failed to apply plugin 'com.android.internal.application'.\n   > Android Gradle plugin requires Java 17 to run. You are currently using Java 11.\n```\n\n## 3. Diagnose\n- Leading hypothesis: The JDK on the runner changed outside the pinned set that AGP requires\n- Next command: java -version; ./gradlew --version; check gradle-wrapper.properties and the AGP version\n\n## 4. Contain and fix\nPin the JDK distribution/version from toolchain.md in setup-java and include it in the cache key\n\n## 5. Verify\nA clean build and a warm cache-hit build both pass\n\n## 6. Complication to rehearse\nAfter the fix, warm builds still fail now and then with 'Unsupported class file major version'. → The cache key lacks the JDK version, so caches compiled with a different JDK are restored\n\n## 7. Senior follow-up\n**Why is deleting every cache not a durable root-cause fix?**\n\n<details><summary>Strong answer</summary>\n\nIt hides the cause, costs build minutes every run, and the problem returns when caching comes back. The real fix is a key that encodes every input that changes the output: OS, architecture, toolchain and lockfiles.\n</details>\n\n## Reference files\n- [.github/workflows/pr-ci.yml](../../.github/workflows/pr-ci.yml)\n- [docs/toolchain.md](../../docs/toolchain.md)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/07-poisoned-or-stale-dependency-cache/README.md":"# Drill 7: Poisoned or stale dependency cache\n\n**Lab:** Either · **Area:** CI\n\n> Like you're 10: Someone ate last week's sandwich because the lunchbox wasn't labeled with the day.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, removed the lockfile hash from the cache key.\n\n## 2. Expected symptom\nClean builds pass, warm builds fail or quietly use old dependencies.\n\nExample (redacted) output, pr-ci #1077 · android-verify (warm):\n```\nCache restored from key: gradle-Linux\n> Task :app:dependencies\nreleaseRuntimeClasspath\n+--- com.squareup.okhttp3:okhttp:4.11.0\n# gradle.lockfile pins okhttp 4.12.0\ne: Unresolved reference: newBuilderWithTimeout\n```\n\n## 3. Diagnose\n- Leading hypothesis: The cache key lacks lockfile/toolchain inputs, so a stale dependency cache is restored\n- Next command: Compare resolved dependency graphs on clean vs warm runs and read the cache restore key in the logs\n\n## 4. Contain and fix\nKey on OS, arch, toolchain and hashFiles of lockfiles and wrapper; untrusted runs don't write caches release jobs read\n\n## 5. Verify\nDeliberately change a dependency and confirm the new key misses and resolves correctly\n\n## 6. Complication to rehearse\nYou learn a fork-triggered run wrote a cache that a release job later restored. → Trust boundary: release jobs must not consume caches untrusted runs can write\n\n## 7. Senior follow-up\n**Which build outputs should never be shared across trust boundaries?**\n\n<details><summary>Strong answer</summary>\n\nCompiled binaries, Gradle build caches, node_modules (postinstall scripts run code), signed artifacts and anything a release job will sign or ship. Untrusted jobs can read safe caches but must not write ones trusted jobs consume.\n</details>\n\n## Reference files\n- [.github/workflows/pr-ci.yml](../../.github/workflows/pr-ci.yml)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/08-flaky-ui-test/README.md":"# Drill 8: Flaky UI test\n\n**Lab:** RouteReady · **Area:** Testing\n\n> Like you're 10: You check the oven after exactly 2 minutes every time. Some days the cookies aren't done yet, and you blame the cookies.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, added random simulator/API delay.\n\n## 2. Expected symptom\nThe route screen assertion fails intermittently.\n\nExample (redacted) output, pr-ci · RouteScreenUITests (20 runs):\n```\nTest Case '-[RouteScreenUITests testShowsBusStatus]' failed (2.104 seconds).\n  XCTAssertTrue failed - Failed to find \"Bus 12 · On time\" after 2.0s\nFailures: 3 / 20 runs\nFixture seed: random (not recorded)\n```\n\n## 3. Diagnose\n- Leading hypothesis: A race between fixture latency and a fixed-time assertion\n- Next command: Inspect the xcresult (screenshots, timing) and rerun many times with a fixed fixture seed\n\n## 4. Contain and fix\nDeterministic fixture server and explicit readiness waits on an accessibility identifier; remove sleeps; quarantine only with an owner and deadline\n\n## 5. Verify\nRepeat 50 times on the declared device matrix and report the failure frequency\n\n## 6. Complication to rehearse\nA teammate proposes auto-retrying failed UI tests in CI. → Only with reporting of flaky rate and a cap; retries can hide a real race users would hit\n\n## 7. Senior follow-up\n**When does a retry conceal a genuine race?**\n\n<details><summary>Strong answer</summary>\n\nWhen the race is in the app, not the test. For example, the UI briefly shows a 'current' bus before the stale check runs. A retry makes CI green while real users still see wrong data.\n</details>\n\n## Reference files\n- [fastlane/Fastfile](../../fastlane/Fastfile)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/09-required-check-stuck-pending/README.md":"# Drill 9: Required check stuck pending\n\n**Lab:** Either · **Area:** CI\n\n> Like you're 10: The hall monitor only works Mondays. On Tuesday, the line never moves.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, changed a contract file the path filters didn't include.\n\n## 2. Expected symptom\nThe PR never finishes, or mobile checks are skipped incorrectly.\n\nExample (redacted) output, PR #73 · checks:\n```\nci-gate         Expected — Waiting for status to be reported\nChanged files: contracts/openapi.yaml\non:\n  pull_request:\n    paths: ['apps/**']\n```\n\n## 3. Diagnose\n- Leading hypothesis: Workflow-level path filtering skipped the whole workflow, so the required check never reported\n- Next command: Inspect the workflow's on.paths, job needs/if and the PR's check runs\n\n## 4. Contain and fix\nAlways trigger the workflow, detect changes in a job, map contracts to all clients, and run the aggregate with if: always()\n\n## 5. Verify\nTest PRs for mobile-only, contract-only, docs-only, workflow-only and lockfile-only changes\n\n## 6. Complication to rehearse\nYou enable a merge queue. Queue entries sit waiting with no checks. → The merge_group trigger on the workflow\n\n## 7. Senior follow-up\n**How does your design work with a merge queue?**\n\n<details><summary>Strong answer</summary>\n\nThe workflow listens to merge_group as well as pull_request. The always-running gate reports for queue entries too, so the queue tests the combined result before it lands on main.\n</details>\n\n## Reference files\n- [scripts/gate.sh](../../scripts/gate.sh)\n- [.github/workflows/pr-ci.yml](../../.github/workflows/pr-ci.yml)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/10-secret-exposure-through-a-pr/README.md":"# Drill 10: Secret exposure through a PR\n\n**Lab:** Either · **Area:** Security · **Interview priority**\n\n> Like you're 10: A visitor asked to use the teacher's desk. The answer key was in the drawer.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, proposed a workflow that runs fork code with release secrets (harmless canary).\n\n## 2. Expected symptom\nA proposed workflow gives untrusted code access to a release environment. The canary showed up in logs.\n\nExample (redacted) output, proposed .github/workflows/build.yml:\n```\non: pull_request_target\njobs:\n  build:\n    environment: release\n    steps:\n      - uses: actions/checkout@v4\n        with: { ref: ${{ github.event.pull_request.head.sha }} }\n      - run: ./scripts/build.sh\n        env: { MATCH_PASSWORD: ${{ secrets.MATCH_PASSWORD }} }\n[log] CANARY_7f3a●●●● printed by scripts/build.sh from fork\n```\n\n## 3. Diagnose\n- Leading hypothesis: A privileged pull_request_target job checks out and runs fork code with secrets\n- Next command: Trace the event, checkout ref, permissions, environment gates and cache/artifact inputs; list which secrets were in scope\n\n## 4. Contain and fix\nStop the job and disable the workflow, rotate any real exposed credentials, audit logs/artifacts/caches; split PR validation (pull_request, no secrets) from trusted release\n\n## 5. Verify\nA fork PR in a test repo cannot read the canary\n\n## 6. Complication to rehearse\nA new design uses workflow_run to sign artifacts produced by the PR build. → Those artifacts are untrusted input; don't sign them. Rebuild from a trusted SHA and validate\n\n## 7. Senior follow-up\n**Why does workflow_run need careful artifact trust validation?**\n\n<details><summary>Strong answer</summary>\n\nworkflow_run runs privileged code, but the artifacts it downloads may have been produced by untrusted PR code. Treat them as data from strangers: validate, never execute or sign them, and build releases from trusted refs.\n</details>\n\n## Reference files\n- [.github/workflows/pr-ci.yml](../../.github/workflows/pr-ci.yml)\n- [docs/branch-protection.md](../../docs/branch-protection.md)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/11-api-breaks-an-installed-client/README.md":"# Drill 11: API breaks an installed client\n\n**Lab:** RouteReady · **Area:** API · **Interview priority**\n\n> Like you're 10: You ripped out the old skinny bike-rack slots. Every kid on an old bike now has nowhere to park.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, changed delay_minutes from a number to a string.\n\n## 2. Expected symptom\nThe new client works; the previous client fails to parse route status.\n\nExample (redacted) output, RouteReady iOS 1.3 (installed) · crash log:\n```\nDecodingError.typeMismatch(Swift.Int, Context(\n  codingPath: [status, delay_minutes],\n  debugDescription: \"Expected to decode Int but found a string instead.\"))\nAPI deploy: routeready-api@sha256:4be1●●●● (12 min ago)\nInstalled: 1.3 (12%), 1.4 (61%), 1.5 phased (27%)\n```\n\n## 3. Diagnose\n- Leading hypothesis: The backend changed a field's type; 1.3 is still installed and can't decode it\n- Next command: Replay recorded 1.3 fixtures against the candidate API and run a contract diff old vs new\n\n## 4. Contain and fix\nRestore the additive shape (revert the backend to a compatible digest or forward-fix), and disable the new behavior flag\n\n## 5. Verify\nPrevious and current client contract tests pass as a required PR check\n\n## 6. Complication to rehearse\nReverting the backend would also revert a migration that 1.5 depends on. → Roll forward: a compatible backend fix that serves both shapes; never roll back schema blindly\n\n## 7. Senior follow-up\n**Why can't you just require all users to update immediately?**\n\n<details><summary>Strong answer</summary>\n\nStore review takes time, users delay updates, some devices can't run the newest OS, some are offline, and a force-update screen itself requires the old app to parse the server's response. Installed apps outlive any single deployment.\n</details>\n\n## Reference files\n- [scripts/contract-check.sh](../../scripts/contract-check.sh)\n- [contracts/openapi.yaml](../../contracts/openapi.yaml)\n- [contracts/fixtures/v1.3/route-status.json](../../contracts/fixtures/v1.3/route-status.json)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/12-stale-or-out-of-order-gps-data/README.md":"# Drill 12: Stale or out-of-order GPS data\n\n**Lab:** RouteReady · **Area:** Data\n\n> Like you're 10: An old postcard arrives late and you think your friend went back home. And when postcards stop, you assume they're still where the last one said.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, sent sequence 102, then 99, then stopped the producer.\n\n## 2. Expected symptom\nThe bus appears to move backward, or stays 'current' after updates stop.\n\nExample (redacted) output, telemetry · bus_id=bus-12:\n```\nevent_id=e-71a seq=102 observed_at=14:03:10Z received_at=14:03:11Z  ACCEPTED\nevent_id=e-6f0 seq=99  observed_at=14:02:40Z received_at=14:03:12Z  ACCEPTED (replaced current)\n-- no events after 14:03:12Z --\nclient 14:06:30: \"Bus 12 — 2 min away\" (no freshness shown)\n```\n\n## 3. Diagnose\n- Leading hypothesis: The server orders by received time, and the client has no freshness indicator\n- Next command: Query telemetry for the bus comparing observed_at, received_at, sequence and event_id\n\n## 4. Contain and fix\nKeep the latest position by sequence/observed_at, ignore older events (stored idempotently by event_id), show 'stale' after 60s without fresh data\n\n## 5. Verify\nFake-clock and out-of-order tests: 102 then 99 keeps 102; no events for 60s shows stale\n\n## 6. Complication to rehearse\nThe producer reboots and its sequence restarts at 1. → Add a producer boot/epoch ID and order by (epoch, sequence), with observed_at and a documented clock-skew allowance as a check\n\n## 7. Senior follow-up\n**How do you handle producer reboot, sequence reset and clock skew?**\n\n<details><summary>Strong answer</summary>\n\nScope sequence numbers with a boot epoch, accept a documented skew window on observed_at, record received_at for diagnosis, and flag events far outside the window rather than silently trusting or dropping them.\n</details>\n\n## Reference files\n- [services/api/src/main/java/org/routeready/telemetry/TelemetryIngestService.java](../../services/api/src/main/java/org/routeready/telemetry/TelemetryIngestService.java)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/13-backend-readiness-and-bad-rollout/README.md":"# Drill 13: Backend readiness and bad rollout\n\n**Lab:** RouteReady · **Area:** Backend\n\n> Like you're 10: A student says 'I'm ready!' before finding their pencil. The teacher calls on them anyway.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, made the container report healthy before its database pool was ready.\n\n## 2. Expected symptom\nThe deployment passes, but mobile requests fail intermittently for minutes.\n\nExample (redacted) output, routeready-api · rollout:\n```\npod api-7d9f ready=true after 3s\nHikariPool-1 - Connection is not available, request timed out after 30000ms.\nGET /api/v1/routes/r-2/status 503 (x214 in 4m)\nreadinessProbe: GET /actuator/health/liveness\n```\n\n## 3. Diagnose\n- Leading hypothesis: Readiness reports ready before the DB pool is usable (it's pointed at the liveness endpoint)\n- Next command: Compare liveness vs readiness endpoint behavior and pod events with kubectl describe\n\n## 4. Contain and fix\nReadiness includes required dependencies, liveness doesn't; bounded startup; revert to the previous compatible digest if needed\n\n## 5. Verify\nDuring a controlled DB outage, pods go unready and receive no traffic, but aren't restarted\n\n## 6. Complication to rehearse\nSomeone adds the database check to the liveness probe 'to be safe'. → Every pod fails liveness and restarts, turning a short blip into a full outage\n\n## 7. Senior follow-up\n**When would a liveness restart make an outage worse?**\n\n<details><summary>Strong answer</summary>\n\nWhen the cause is external, like a slow database. Restarting all pods at once drops in-flight work, causes cold starts and a thundering herd on reconnect, and adds downtime without fixing anything.\n</details>\n\n## Reference files\n- [infra/docker-compose.yml](../../infra/docker-compose.yml)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/14-destructive-database-migration/README.md":"# Drill 14: Destructive database migration\n\n**Lab:** Either · **Area:** Backend\n\n> Like you're 10: You tore down the old hallway before the new one was finished, and half the class is still walking through it.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, dropped a column that previous API versions still read.\n\n## 2. Expected symptom\nA rolling deploy fails after some instances update.\n\nExample (redacted) output, routeready-api · rolling deploy:\n```\nmigration 0009_drop_eta_minutes applied\nv1 pod: ERROR: column \"eta_minutes\" does not exist\nv2 pods: OK\nrollout: 3/6 updated, v1 error rate 41%\n```\n\n## 3. Diagnose\n- Leading hypothesis: The migration removed a column older pods still read during the rollout overlap\n- Next command: Check schema revision, the failing queries and which versions are running\n\n## 4. Contain and fix\nPause the rollout, apply a forward migration restoring the column, then redo it as expand → backfill → transition → contract\n\n## 5. Verify\nCI runs both server versions against the migrated schema\n\n## 6. Complication to rehearse\nv2 has written new rows since the column was dropped. → Backfill the restored column for those rows before old readers rely on it\n\n## 7. Senior follow-up\n**Why is rolling back the application image alone insufficient?**\n\n<details><summary>Strong answer</summary>\n\nThe database already changed. Old code against new schema still fails. Schema changes need their own forward fix and an expand/contract plan so every running version works throughout.\n</details>\n\n## Reference files\n- [services/api/db/migrations/README.md](../../services/api/db/migrations/README.md)\n- [services/api/db/migrations/V7__expand_add_eta_confidence.sql](../../services/api/db/migrations/V7__expand_add_eta_confidence.sql)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/15-store-processing-or-review-delay/README.md":"# Drill 15: Store processing or review delay\n\n**Lab:** Either · **Area:** Release\n\n> Like you're 10: You told everyone Grandma got the present. It's still at the sorting center.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, made the distribution adapter stay in processing/review.\n\n## 2. Expected symptom\nCI upload is green, but testers or users can't install.\n\nExample (redacted) output, release-ios #431 · beta:\n```\n[upload_to_testflight] Successfully uploaded the new binary to App Store Connect\n[poll] build 61 processingState=PROCESSING (t+45m)\n[slack-bot] ✅ RouteReady 1.5 released!\ntester: \"No new build in TestFlight\"\n```\n\n## 3. Diagnose\n- Leading hypothesis: Upload was treated as release; processing/availability/review are separate and still pending\n- Next command: Query App Store Connect for build processing and beta review state and check agreements/metadata\n\n## 4. Contain and fix\nTrack separate states in the manifest, use bounded polling and a scheduled status check, keep the feature off, report truthfully\n\n## 5. Verify\nThe manifest schema rejects 'released' while processing\n\n## 6. Complication to rehearse\nThe backend for 1.5 is already live and marketing wants to announce today. → Keep the flag off (backend is additive, so no impact), share the real state and a next check time\n\n## 7. Senior follow-up\n**How do you communicate a launch delay when backend is already live?**\n\n<details><summary>Strong answer</summary>\n\nState facts: the backend is deployed, additive and dark behind a flag; the binary is in processing/review; here's the next update time. No promises the store controls.\n</details>\n\n## Reference files\n- [scripts/record-state.sh](../../scripts/record-state.sh)\n- [scripts/poll-store-state.sh](../../scripts/poll-store-state.sh)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/16-crash-increase-after-rollout/README.md":"# Drill 16: Crash increase after rollout\n\n**Lab:** Either · **Area:** Operate · **Interview priority**\n\n> Like you're 10: The water slide is making kids bump their heads. Turn off the water (flag), stop the line (pause), fix the slide (new build). You can't un-slide the kids already at the bottom.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, crashed a flagged code path for a disposable cohort.\n\n## 2. Expected symptom\nThe new build's crash rate rises compared to baseline.\n\nExample (redacted) output, crash dashboard · lab fixture:\n```\nrelease      phase        crash-free sessions   sessions\n1.4.2        100%         99.6%                 n=18,400\n1.5.0 (57)   day 2 (~2%)  97.1%                 n=640\ntop crash: ETAConfidenceView.render — 88% of 1.5.0 crashes\nsegment: eta_confidence_enabled=true cohort only\n```\n\n## 3. Diagnose\n- Leading hypothesis: The new flagged code path crashes for the enabled cohort\n- Next command: Segment by release, OS, device, flag cohort and sample size\n\n## 4. Contain and fix\nTurn off eta_confidence_enabled remotely and pause the phased release\n\n## 5. Verify\nCrash rate for the installed 1.5.0 population returns to baseline after the flag is off, and a fixed build with a higher number passes\n\n## 6. Complication to rehearse\nA variant crashes at launch, before flags are fetched. → The flag can't help: rely on safe cached defaults, pause/halt rollout, ship a replacement build (expedited review if needed), use a server mitigation if the crash comes from a response\n\n## 7. Senior follow-up\n**What if the crash occurs before feature flags can be fetched?**\n\n<details><summary>Strong answer</summary>\n\nFlags with server-side defaults won't reach it. Design safe defaults (new features off unless cached on), pause/halt distribution, and ship a replacement binary with a higher build number. If a server response triggers it, change the response.\n</details>\n\n## Reference files\n- [docs/rollout.md](../../docs/rollout.md)\n- [config/feature-flags.json](../../config/feature-flags.json)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/17-wrong-environment-or-tenant-config/README.md":"# Drill 17: Wrong environment or tenant config\n\n**Lab:** StayReady · **Area:** Security\n\n> Like you're 10: Anyone can write any name on a name tag. The teacher has to check the class list, not the tag.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, let tenant identity come from an editable header.\n\n## 2. Expected symptom\nA Cedar Cove guest sees a Harbor House reservation.\n\nExample (redacted) output, stayready-api · access log:\n```\nGET /api/v1/reservations/current\n  auth.sub=guest-cedar-014  X-Tenant-Id: harbor-house\n  200 OK  tenant=harbor-house reservation=res-hh-221\ncode: tenant_id = request.headers.get('X-Tenant-Id')\n```\n\n## 3. Diagnose\n- Leading hypothesis: The server trusts a client header to choose the tenant\n- Next command: Trace the authorization code path and run a negative test with a modified header; check logs for scope\n\n## 4. Contain and fix\nRestrict the endpoint/deploy the fix now, assess exposure from logs; derive tenant from the authenticated identity server-side\n\n## 5. Verify\nNegative cross-tenant tests (IDs and headers) fail closed in CI\n\n## 6. Complication to rehearse\nYou also find the production candidate IPA has a staging API URL baked in. → A preflight that inspects compiled public config against the target environment before upload\n\n## 7. Senior follow-up\n**Which configuration is safe to bundle in a mobile app?**\n\n<details><summary>Strong answer</summary>\n\nPublic things: API base URL, environment name, public crash-reporting DSN, theme, flag defaults. Never anything that grants privilege: API secrets, signing keys, admin tokens. Anything in the app can be read by anyone.\n</details>\n\n## Reference files\n- [stayready/services/api/app/reservations.py](../../stayready/services/api/app/reservations.py)\n- [scripts/preflight-env.sh](../../scripts/preflight-env.sh)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/18-offline-duplicate-service-request/README.md":"# Drill 18: Offline duplicate service request\n\n**Lab:** StayReady · **Area:** API\n\n> Like you're 10: You mailed a letter, never heard back, mailed it again. Now the plumber shows up twice.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, committed a request, then dropped the response so the client retried.\n\n## 2. Expected symptom\nTwo maintenance tickets for one tap.\n\nExample (redacted) output, stayready · service_requests:\n```\nclient: POST /service-requests key=7c1e… → timeout (server committed)\nclient: reconnect, retry POST key=7c1e…\ndb: #881 tenant=cedar-cove 'Leaking faucet' 18:02:11\ndb: #882 tenant=cedar-cove 'Leaking faucet' 18:02:13\n```\n\n## 3. Diagnose\n- Leading hypothesis: The retry after commit isn't deduplicated atomically by idempotency key\n- Next command: Trace the key in request logs and the DB; check for a unique constraint and transaction boundaries\n\n## 4. Contain and fix\nUnique (tenant_id, idempotency_key); store the original response in the same transaction; on conflict return it; client reuses the key\n\n## 5. Verify\nReal network-response loss (proxy drops the reply after commit) plus concurrent retries create exactly one row\n\n## 6. Complication to rehearse\nA client bug sends the same key with a different description. → Reject with a clear error (409/422); don't return the old result or overwrite\n\n## 7. Senior follow-up\n**How should the server handle the same key with a different payload?**\n\n<details><summary>Strong answer</summary>\n\nStore a hash of the original payload with the key. On replay, compare hashes: same returns the stored response, different returns a conflict error so the client bug surfaces.\n</details>\n\n## Reference files\n- [stayready/services/api/app/service_requests.py](../../stayready/services/api/app/service_requests.py)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/19-crash-report-lacks-usable-symbols/README.md":"# Drill 19: Crash report lacks usable symbols\n\n**Lab:** StayReady · **Area:** Observability\n\n> Like you're 10: The smoke detector rings but nobody labeled the rooms.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, skipped dSYM/source-map upload for the shipped build.\n\n## 2. Expected symptom\nThe stack trace is unreadable or points to the wrong source line.\n\nExample (redacted) output, crash report · StayReady 2.1 (140):\n```\nThread 0 Crashed:\n0  StayReady   0x0000000104a2c3f8 StayReady + 1234936\n1  StayReady   0x0000000104a1b210 StayReady + 1164560\nwarning: missing dSYM for UUID 9A1B●●●●-…\nJS: index.android.bundle:1:48211 (no source map for dist=140)\n```\n\n## 3. Diagnose\n- Leading hypothesis: The exact build's dSYM/source map wasn't uploaded, or another build's was\n- Next command: dwarfdump --uuid on the retained dSYM vs the crash UUID; compare release/dist with the manifest\n\n## 4. Contain and fix\nUpload the exact retained dSYMs/maps from the shipped build artifact with correct release and dist\n\n## 5. Verify\nA controlled crash resolves to the expected source line\n\n## 6. Complication to rehearse\nThe build's CI artifacts expired after 7 days. → Symbol retention must exceed the support window; store them with the manifest in long-term artifact storage\n\n## 7. Senior follow-up\n**Why may rebuilding the same Git SHA produce unusable replacement symbols?**\n\n<details><summary>Strong answer</summary>\n\nEach compile produces new binary UUIDs and can differ in toolchain, flags or code layout. Symbols must come from the exact binary users are running.\n</details>\n\n## Reference files\n- [scripts/upload-symbols.sh](../../scripts/upload-symbols.sh)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/20-incompatible-ota-update-unsafe-ai-change/README.md":"# Drill 20: Incompatible OTA update / unsafe AI change\n\n**Lab:** StayReady · **Area:** AI + RN\n\n> Like you're 10: You can download new game levels to your console, but you can't download a new controller over Wi-Fi.\n\n## 1. Inject (disposable branch only)\nIn a throwaway branch or sandbox, had an AI-generated PR add a native dependency and propose a JS-only update.\n\n## 2. Expected symptom\nOld installed clients crash: the native module doesn't exist.\n\nExample (redacted) output, PR #96 'Add camera check-in' (AI-generated, 1,812 lines):\n```\npackage.json: + \"react-native-vision-camera\"\nios/Podfile.lock: + VisionCamera\nrelease plan: eas update --channel production (runtimeVersion unchanged)\ninstalled 2.1: Invariant Violation: requireNativeComponent: \"CameraView\" was not found in the UIManager.\n```\n\n## 3. Diagnose\n- Leading hypothesis: Native code was shipped through a JS-only update to binaries that lack the module, with the runtime version unchanged\n- Next command: Review the native diff (Podfile.lock, android/, native modules), runtime version policy and channel\n\n## 4. Contain and fix\nBlock publication or republish the last compatible update; build a new binary with a new runtime version; split the PR; add a preflight\n\n## 5. Verify\nA CI test proves a native change can't take the OTA-only path\n\n## 6. Complication to rehearse\nThe AI PR is green and 1,812 lines long. Your reviewer says 'CI passed, approve it'. → Split it, explain every generated command, check native diffs, secrets and tests; green CI isn't judgment\n\n## 7. Senior follow-up\n**Why does approving a green PR still require engineering judgment?**\n\n<details><summary>Strong answer</summary>\n\nCI only checks what tests cover. It won't notice an unsafe release path, a secret in a script, an over-broad permission or a command nobody understands. I review the native diff, run the risky paths, and can explain every line before approving.\n</details>\n\n## Reference files\n- [stayready/mobile/app.config.snippet.json](../../stayready/mobile/app.config.snippet.json)\n\n## Evidence to save\n- [ ] Failing run (link or log)\n- [ ] Hypotheses you rejected\n- [ ] Commands and their output\n- [ ] Fix PR + passing run\n- [ ] `incident.md` from [drills/_template/incident.md](../_template/incident.md)\n","drills/README.md":"# Drills\n\nRun each drill in a disposable branch. Save: the failing run, your hypotheses, the commands, the fix, the passing run, and `incident.md` (copy `_template/incident.md`).\nSigning drills use test assets or preflight fixtures. Never revoke real certificates.\nPriority for the interview: **1, 3, 4, 10, 11, 16**.\n","drills/_template/incident.md":"# Incident note: <drill title>  (portfolio lab)\n\n- **Impact and scope:**\n- **First signal:**\n- **Timeline (relative):** T+0 inject · T+? signal · T+? hypothesis · T+? contained · T+? verified\n- **Hypotheses rejected:**\n- **Root cause:**\n- **Containment:**\n- **Corrective change:** (PR link)\n- **Regression test:** (test name + link)\n- **Prevention owner:**\n- **Evidence:** failing run · passing run · command output\n","evidence/README.md":"# Evidence\n\nEvery claim in an interview should link to something here: a real command output, a CI run, a manifest.\n\n| Claim | Evidence | Status |\n|---|---|---|\n| PR CI blocks a failing unit test | link to failing run + passing run | NOT STARTED |\n| Breaking contract change blocked | `contract-check.txt` from the blocked PR | NOT STARTED |\n| Signed iOS build | manifest + IPA checksum, or BLOCKED (no Apple account) | BLOCKED until account |\n| Signed Android AAB | manifest + AAB checksum | NOT STARTED |\n| Fork cannot read release secrets | canary drill run | NOT STARTED |\n\nStatuses: **IMPLEMENTED** (code exists), **VERIFIED** (ran successfully, output saved), **SIMULATED** (fixture or dry run, says so), **BLOCKED** (missing prerequisite, named).\nNever mark a build, signing operation, upload or deployment VERIFIED unless it actually ran.\n","evidence/release-manifest.schema.json":"{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"title\": \"Release manifest\",\n  \"type\": \"object\",\n  \"additionalProperties\": false,\n  \"required\": [\"application_id\", \"platform\", \"marketing_version\", \"build_number\", \"git_sha\", \"workflow_run_id\",\n               \"artifact_sha256\", \"backend_image_digest\", \"api_contract_revision\", \"store_state\", \"distribution_status\"],\n  \"properties\": {\n    \"application_id\": { \"type\": \"string\" },\n    \"platform\": { \"enum\": [\"ios\", \"android\"] },\n    \"marketing_version\": { \"type\": \"string\" },\n    \"build_number\": { \"type\": \"integer\", \"minimum\": 1, \"maximum\": 2100000000 },\n    \"git_sha\": { \"type\": \"string\", \"pattern\": \"^[0-9a-f]{40}$\" },\n    \"workflow_run_id\": { \"type\": \"string\" },\n    \"toolchain\": { \"type\": \"object\" },\n    \"artifact\": { \"type\": \"string\" },\n    \"artifact_sha256\": { \"type\": \"string\", \"pattern\": \"^[0-9a-f]{64}$\" },\n    \"symbol_artifact_ids\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"backend_image_digest\": { \"type\": \"string\", \"description\": \"registry/name@sha256:..., never a tag\" },\n    \"api_contract_revision\": { \"type\": \"string\" },\n    \"tested_client_versions\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"feature_flag_defaults\": { \"type\": \"object\" },\n    \"target_track\": { \"type\": \"string\" },\n    \"approvals\": { \"type\": \"array\", \"items\": { \"type\": \"object\" } },\n    \"store_state\": { \"enum\": [\"not_uploaded\", \"uploaded\", \"processing\", \"testers_available\", \"in_review\", \"approved\", \"phased_release\", \"staged_rollout\", \"paused\", \"halted\", \"released\"] },\n    \"distribution_status\": { \"enum\": [\"packaged\", \"uploaded\", \"testing\", \"in_review\", \"rolling_out\", \"released\", \"paused\"] }\n  },\n  \"not\": { \"anyOf\": [ { \"required\": [\"keystore_password\"] }, { \"required\": [\"token\"] }, { \"required\": [\"private_key\"] } ] }\n}\n","fastlane/Appfile":"app_identifier(\"org.routeready.parent\")   # fictional lab bundle ID; must match your App ID\n# team_id comes from env (FASTLANE_TEAM_ID) so it never sits in source\n","fastlane/Fastfile":"# Lane contract (playbook): verify / package / beta / promote per platform.\n# CI never creates, regenerates or revokes signing assets.\n# Note: `sh` runs from the fastlane/ folder, so scripts are called with ../\n# Journey stations 3, 8, 10, 12 · Bug Hunt b4, b5 · Drills 1, 2, 3, 4\n\ndefault_platform(:ios)\n\ndef asc_key\n  app_store_connect_api_key(\n    key_id: ENV.fetch(\"ASC_KEY_ID\"),\n    issuer_id: ENV.fetch(\"ASC_ISSUER_ID\"),\n    key_content: ENV.fetch(\"ASC_KEY_P8_BASE64\"),\n    is_key_content_base64: true\n  )\nend\n\nplatform :ios do\n  desc \"Simulator build + tests. No signing secrets. Saves the xcresult.\"\n  lane :verify do |opts|\n    destination = opts[:destination] || UI.user_error!(\"pass destination: from scripts/pick-simulator.sh\")\n    run_tests(\n      project: \"apps/ios/RouteReady.xcodeproj\",\n      scheme: \"RouteReady\",\n      destination: destination,\n      result_bundle: true,\n      output_directory: \"build/ios\",\n      code_coverage: true\n    )\n  end\n\n  desc \"Trusted release only. Temp keychain, readonly match, signed IPA + dSYMs, manifest.\"\n  lane :package do |opts|\n    build_number = opts[:build_number] || UI.user_error!(\"allocate first: scripts/allocate-build-number.sh\")\n    sh(\"../scripts/release-preflight.sh\", \"package\", \"ios\", build_number.to_s)\n    setup_ci                                   # temporary keychain on CI; puts match in readonly mode\n    match(type: \"appstore\", readonly: true)    # fetch existing cert + profile only\n    sh(\"../scripts/signing-preflight-ios.sh\")  # bundle ID, team, entitlements vs decoded profile (drill 1)\n    increment_build_number(xcodeproj: \"apps/ios/RouteReady.xcodeproj\", build_number: build_number)\n    build_app(\n      project: \"apps/ios/RouteReady.xcodeproj\",\n      scheme: \"RouteReady\",\n      export_method: \"app-store\",\n      output_directory: \"build/ios\",\n      output_name: \"RouteReady.ipa\",\n      include_symbols: true\n    )\n    sh(\"../scripts/write-manifest.sh\", \"ios\", \"../build/ios/RouteReady.ipa\", build_number.to_s)\n  end\n\n  desc \"Upload an EXISTING IPA. Never rebuilds. Records 'uploaded', not 'released'.\"\n  lane :beta do |opts|\n    ipa = opts[:ipa] || UI.user_error!(\"pass ipa: produced by the package lane\")\n    manifest = opts[:manifest] || UI.user_error!(\"pass manifest:\")\n    sh(\"../scripts/verify-manifest.sh\", \"../#{ipa}\", \"../#{manifest}\")\n    asc_key\n    upload_to_testflight(ipa: ipa, skip_waiting_for_build_processing: true)\n    sh(\"../scripts/record-state.sh\", \"ios\", \"uploaded\")\n  end\n\n  desc \"Submit an existing processed build for App Review. No binary upload.\"\n  lane :promote do |opts|\n    asc_key\n    deliver(\n      build_number: opts[:build_number].to_s,\n      submit_for_review: true,\n      skip_binary_upload: true,\n      skip_metadata: true,\n      skip_screenshots: true,\n      phased_release: true,          # Apple's fixed 7-day schedule for automatic updates\n      automatic_release: false,      # you release after approval\n      force: true\n    )\n    sh(\"../scripts/record-state.sh\", \"ios\", \"in_review\")\n  end\nend\n\nplatform :android do\n  desc \"Lint + unit tests + debug build. No signing secrets.\"\n  lane :verify do\n    gradle(project_dir: \"apps/android\", tasks: [\"lint\", \"testDebugUnitTest\", \"assembleDebug\"])\n  end\n\n  desc \"Trusted release only. Signed AAB (upload key) + mapping, fingerprint preflight, manifest.\"\n  lane :package do |opts|\n    version_code = opts[:version_code] || UI.user_error!(\"allocate first: scripts/allocate-build-number.sh\")\n    sh(\"../scripts/release-preflight.sh\", \"package\", \"android\", version_code.to_s)\n    gradle(\n      project_dir: \"apps/android\",\n      task: \"bundle\",\n      build_type: \"Release\",\n      properties: { \"routereadyVersionCode\" => version_code.to_s }\n    )\n    aab = \"../apps/android/app/build/outputs/bundle/release/app-release.aab\"\n    sh(\"../scripts/verify-upload-cert.sh\", aab)   # drill 3\n    sh(\"../scripts/write-manifest.sh\", \"android\", aab, version_code.to_s)\n  end\n\n  desc \"Upload an EXISTING AAB to the internal track.\"\n  lane :beta do |opts|\n    aab = opts[:aab] || UI.user_error!(\"pass aab:\")\n    manifest = opts[:manifest] || UI.user_error!(\"pass manifest:\")\n    sh(\"../scripts/verify-manifest.sh\", \"../#{aab}\", \"../#{manifest}\")\n    upload_to_play_store(\n      aab: aab,\n      track: \"internal\",\n      json_key_data: ENV.fetch(\"PLAY_JSON_KEY\"),\n      skip_upload_metadata: true,\n      skip_upload_images: true,\n      skip_upload_screenshots: true\n    )\n    sh(\"../scripts/record-state.sh\", \"android\", \"uploaded\")\n  end\n\n  desc \"Promote the existing versionCode from internal to production as a staged rollout.\"\n  lane :promote do |opts|\n    upload_to_play_store(\n      track: \"internal\",\n      track_promote_to: \"production\",\n      version_code: opts[:build_number].to_i,\n      rollout: (opts[:rollout] || \"0.1\").to_s,\n      json_key_data: ENV.fetch(\"PLAY_JSON_KEY\"),\n      skip_upload_aab: true,\n      skip_upload_apk: true,\n      skip_upload_metadata: true,\n      skip_upload_images: true,\n      skip_upload_screenshots: true\n    )\n    sh(\"../scripts/record-state.sh\", \"android\", \"staged_rollout\")\n  end\nend\n","fastlane/Matchfile":"# Read-only in CI. Certificates are created ONCE by an authorized admin, locally:\n#   bundle exec fastlane match appstore      (admin machine, not CI)\ngit_url(ENV[\"MATCH_GIT_URL\"])\nstorage_mode(\"git\")\ntype(\"appstore\")\napp_identifier([\"org.routeready.parent\"])\nreadonly(true)\n","infra/docker-compose.yml":"# Local lab: API + Postgres + synthetic GPS producer. No cloud account needed.\nservices:\n  db:\n    image: postgres:<VERIFY>\n    environment:\n      POSTGRES_PASSWORD: lab-only-not-a-secret\n      POSTGRES_DB: routeready\n    ports: [\"5432:5432\"]\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U postgres\"]\n      interval: 5s\n      retries: 10\n  api:\n    build: ../services/api\n    environment:\n      DATABASE_URL: jdbc:postgresql://db:5432/routeready\n    ports: [\"8080:8080\"]\n    depends_on:\n      db: { condition: service_healthy }\n    healthcheck:   # readiness includes the DB; liveness (in the app) does not (drill 13)\n      test: [\"CMD\", \"curl\", \"-fsS\", \"http://localhost:8080/actuator/health/readiness\"]\n      interval: 5s\n      retries: 20\n  producer:\n    build: ../services/producer\n    environment:\n      API_URL: http://api:8080\n      PRODUCER_TOKEN: lab-only-producer-token\n    depends_on:\n      api: { condition: service_healthy }\n","scripts/allocate-build-number.sh":"#!/usr/bin/env bash\n# Durable, concurrency-safe build-number allocator (drill 4, Bug Hunt b5).\n# Store: allocations.json on a dedicated branch; git push is the compare-and-swap.\n# Usage: allocate-build-number.sh <ios|android> <application_id> <git_sha>\n# Optional: STORE_LATEST = highest number the store already has (latest_testflight_build_number,\n#           google_play_track_version_codes). The allocator never goes below it.\nset -euo pipefail\nplatform=$1 app=$2 sha=$3\nbranch=${ALLOCATOR_BRANCH:-build-numbers}\nkey=\"$app/$platform\"\nrun=\"${GITHUB_RUN_ID:-local}\"          # a re-run of the same workflow run reuses its number\nremote=$(git config --get remote.origin.url)\nwork=$(mktemp -d); trap 'rm -rf \"$work\"' EXIT\n\nfor attempt in 1 2 3 4 5; do\n  rm -rf \"$work/s\"\n  if ! git clone --quiet --depth 1 --branch \"$branch\" \"$remote\" \"$work/s\" 2>/dev/null; then\n    echo \"allocator branch '$branch' not found; create it with allocations.json containing {}\" >&2; exit 2\n  fi\n  f=\"$work/s/allocations.json\"\n  existing=$(jq -r --arg k \"$key\" --arg r \"$sha@$run\" '.[$k].byRun[$r] // empty' \"$f\")\n  if [[ -n \"$existing\" ]]; then echo \"$existing\"; exit 0; fi\n  last=$(jq -r --arg k \"$key\" '.[$k].last // 0' \"$f\")\n  floor=${STORE_LATEST:-0}\n  next=$(( (last > floor ? last : floor) + 1 ))\n  jq --arg k \"$key\" --arg r \"$sha@$run\" --argjson n \"$next\" \\\n     '.[$k].last = $n | .[$k].byRun[$r] = $n' \"$f\" > \"$f.tmp\" && mv \"$f.tmp\" \"$f\"\n  if (cd \"$work/s\" && git add allocations.json \\\n      && git -c user.name=allocator -c user.email=allocator@users.noreply.github.com commit -qm \"allocate $key=$next for $sha\" \\\n      && git push --quiet origin \"$branch\"); then\n    echo \"$next\"; exit 0\n  fi\n  echo \"allocation race, retrying ($attempt)\" >&2\n  sleep $(( attempt * 2 ))\ndone\necho \"could not allocate a build number after 5 attempts\" >&2\nexit 1\n","scripts/contract-check.sh":"#!/usr/bin/env bash\n# Block breaking API changes and replay previous-client fixtures (drill 11, Bug Hunt b9).\n# Usage: contract-check.sh <base-ref>\nset -euo pipefail\nbase=${1:-origin/main}\nmkdir -p evidence\ngit show \"$base:contracts/openapi.yaml\" > /tmp/openapi-base.yaml\n# oasdiff flags removed fields, type changes and new enum values in responses as breaking.\noasdiff breaking /tmp/openapi-base.yaml contracts/openapi.yaml --fail-on ERR | tee evidence/contract-check.txt\n# Old-client fixtures are replayed by the API test suite against the candidate:\n./services/api/gradlew -p services/api contractTest -PclientFixtures=contracts/fixtures | tee -a evidence/contract-check.txt\n","scripts/deploy-staging.sh":"#!/usr/bin/env bash\n# Deploy an image BY DIGEST to staging. Replace the body with your platform (ECS, Cloud Run, k8s).\nset -euo pipefail\nimage=${1:?usage: deploy-staging.sh <registry/name@sha256:...>}\n[[ \"$image\" == *@sha256:* ]] || { echo \"refusing to deploy a tag; pass a digest\" >&2; exit 1; }\necho \"deploying $image to staging\"\n# e.g. kubectl -n staging set image deploy/routeready-api api=\"$image\" && kubectl -n staging rollout status deploy/routeready-api\n","scripts/gate.sh":"#!/usr/bin/env bash\n# Aggregate required check (drill 9, Bug Hunt b10).\n# \"skipped\" is fine (job didn't apply). \"failure\" or \"cancelled\" fails the gate.\nset -euo pipefail\necho \"$NEEDS_JSON\" | jq -r 'to_entries[] | \"\\(.key)=\\(.value.result)\"'\nif [[ \"$(echo \"$NEEDS_JSON\" | jq -r '.changes.result')\" != \"success\" ]]; then\n  echo \"change detection did not succeed\" >&2; exit 1\nfi\nbad=$(echo \"$NEEDS_JSON\" | jq -r 'to_entries[] | select(.value.result==\"failure\" or .value.result==\"cancelled\") | .key')\nif [[ -n \"$bad\" ]]; then echo \"failed or cancelled: $bad\" >&2; exit 1; fi\necho \"ci-gate: all applicable jobs passed\"\n","scripts/pick-simulator.sh":"#!/usr/bin/env bash\n# Pick an AVAILABLE simulator instead of hardcoding a name that a runner image may drop (drill 5).\n# Prefers IOS_RUNTIME (e.g. \"iOS-18\") and DEVICE_PREFIX (default \"iPhone\") from docs/toolchain.md.\nset -euo pipefail\nruntime=\"${IOS_RUNTIME:-}\"\nprefix=\"${DEVICE_PREFIX:-iPhone}\"\njson=$(xcrun simctl list devices available --json)\nudid=$(echo \"$json\" | jq -r --arg rt \"$runtime\" --arg p \"$prefix\" '\n  .devices | to_entries\n  | map(select(.key | test(\"SimRuntime.iOS\")))\n  | map(select($rt == \"\" or (.key | contains($rt))))\n  | sort_by(.key) | reverse\n  | map(.value[] | select(.name | startswith($p))) | .[0].udid // empty')\nif [[ -z \"$udid\" ]]; then\n  echo \"No available simulator for runtime='$runtime' prefix='$prefix'. Available:\" >&2\n  xcrun simctl list devices available >&2\n  exit 1\nfi\necho \"platform=iOS Simulator,id=$udid\"\n","scripts/poll-store-state.sh":"#!/usr/bin/env bash\n# Bounded polling: report the real state, never loop forever, never claim 'released' early.\n# Usage: poll-store-state.sh <timeout-seconds> <command that prints the current state>\nset -euo pipefail\ntimeout=$1; shift\ndeadline=$(( $(date +%s) + timeout ))\nwhile :; do\n  state=$(\"$@\" || echo \"unknown\")\n  echo \"$(date -u +%H:%M:%SZ) state=$state\"\n  case \"$state\" in testers_available|approved|released) exit 0 ;; rejected|invalid) exit 1 ;; esac\n  (( $(date +%s) < deadline )) || { echo \"still $state after ${timeout}s; reporting pending, not failed\" ; exit 0; }\n  sleep 60\ndone\n","scripts/preflight-env.sh":"#!/usr/bin/env bash\n# Check the CANDIDATE's compiled public config matches the target environment (drill 17).\n# Usage: preflight-env.sh <ios|android> <artifact> <production|staging>\nset -euo pipefail\nplatform=$1 artifact=$2 target=$3\nwant=$(jq -r --arg t \"$target\" '.environments[$t].api_base_url' config/apps.json)\ncase \"$platform\" in\n  ios) got=$(unzip -p \"$artifact\" 'Payload/*.app/Info.plist' | plutil -extract API_BASE_URL raw -o - -) ;;\n  android) got=$(unzip -p \"$artifact\" base/assets/env.json | jq -r '.api_base_url') ;;\nesac\n[[ \"$got\" == \"$want\" ]] || { echo \"candidate points at $got, $target expects $want\" >&2; exit 1; }\necho \"environment ok: $got\"\n","scripts/print-toolchain.sh":"#!/usr/bin/env bash\n# Print the toolchain actually in use so every CI log is evidence (drills 5, 6).\nset -euo pipefail\ncase \"${1:-all}\" in\n  ios)\n    sw_vers; xcodebuild -version; xcode-select -p\n    xcrun simctl list runtimes available\n    ruby -v; bundle -v; bundle exec fastlane --version | tail -n 1 ;;\n  android)\n    java -version 2>&1; ./apps/android/gradlew -p apps/android --version\n    ruby -v; bundle -v ;;\n  *) \"$0\" ios || true; \"$0\" android || true ;;\nesac\n","scripts/record-state.sh":"#!/usr/bin/env bash\n# Append a distribution state change. States are separate on purpose (drill 15):\n# packaged -> uploaded -> processing -> testers_available -> in_review -> approved\n#          -> phased_release | staged_rollout -> released     (+ paused / halted)\nset -euo pipefail\nplatform=$1 state=$2\nallowed=\"packaged uploaded processing testers_available in_review approved phased_release staged_rollout paused halted released\"\n[[ \" $allowed \" == *\" $state \"* ]] || { echo \"unknown state: $state\" >&2; exit 1; }\nroot=$(git rev-parse --show-toplevel)\njq -nc --arg p \"$platform\" --arg s \"$state\" --arg t \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\" --arg run \"${GITHUB_RUN_ID:-local}\" \\\n  '{platform:$p, state:$s, at:$t, run:$run}' >> \"$root/evidence/states.jsonl\"\necho \"state recorded: $platform $state\"\n","scripts/release-preflight.sh":"#!/usr/bin/env bash\n# Release preflight (lane contract). Fails fast before anything is signed or uploaded.\n# Usage: release-preflight.sh <package|promote> <ios|android> <build_number>\nset -euo pipefail\nstage=$1 platform=$2 number=$3\nroot=$(git rev-parse --show-toplevel)\nfail() { echo \"PREFLIGHT FAIL: $*\" >&2; exit 1; }\n\n# 1. Trusted commit: on main, and the SHA is on origin/main\n[[ \"${GITHUB_REF:-refs/heads/main}\" == \"refs/heads/main\" ]] || fail \"releases only run from main (got $GITHUB_REF)\"\ngit fetch --quiet origin main\ngit merge-base --is-ancestor HEAD origin/main || fail \"HEAD is not on origin/main\"\n\n# 2. Exact application identity from config/apps.json\nexpected=$(jq -r --arg p \"$platform\" '.[$p].application_id' \"$root/config/apps.json\")\n[[ -n \"$expected\" && \"$expected\" != \"null\" ]] || fail \"no application_id for $platform in config/apps.json\"\n\n# 3. Build number shape\n[[ \"$number\" =~ ^[0-9]+$ ]] || fail \"build number must be an integer\"\nif [[ \"$platform\" == android && \"$number\" -gt 2100000000 ]]; then fail \"versionCode above Play's limit\"; fi\n\n# 4. Required configuration present (names only — never print values)\ncase \"$platform/$stage\" in\n  ios/package)     req=(MATCH_GIT_URL MATCH_PASSWORD) ;;\n  android/package) req=(ROUTEREADY_UPLOAD_KEYSTORE ROUTEREADY_UPLOAD_STORE_PASSWORD ROUTEREADY_UPLOAD_KEY_ALIAS EXPECTED_UPLOAD_CERT_SHA256) ;;\n  ios/promote)     req=(ASC_KEY_ID ASC_ISSUER_ID ASC_KEY_P8_BASE64) ;;\n  android/promote) req=(PLAY_JSON_KEY) ;;\nesac\nfor v in \"${req[@]}\"; do [[ -n \"${!v:-}\" ]] || fail \"missing required setting: $v\"; done\n\n# 5. Promotion needs compatibility evidence for the candidate\nif [[ \"$stage\" == promote ]]; then\n  [[ -f \"$root/evidence/contract-check.txt\" ]] || fail \"no contract compatibility evidence (scripts/contract-check.sh)\"\nfi\necho \"preflight ok: $stage $platform $expected #$number\"\n","scripts/signing-preflight-ios.sh":"#!/usr/bin/env bash\n# Compare what the target asks for with what the provisioning profile grants (drill 1).\nset -euo pipefail\nsettings=$(xcodebuild -showBuildSettings -project apps/ios/RouteReady.xcodeproj -scheme RouteReady -configuration Release 2>/dev/null)\nbundle=$(echo \"$settings\" | awk -F' = ' '/ PRODUCT_BUNDLE_IDENTIFIER /{print $2; exit}')\nents=$(echo \"$settings\" | awk -F' = ' '/ CODE_SIGN_ENTITLEMENTS /{print $2; exit}')\nprofile=$(ls ~/Library/MobileDevice/Provisioning\\ Profiles/*.mobileprovision | head -n 1)\ndecoded=$(security cms -D -i \"$profile\")\napp_id=$(echo \"$decoded\" | plutil -extract Entitlements.application-identifier raw -o - -)\n[[ \"$app_id\" == *\".$bundle\" ]] || { echo \"profile app ID $app_id does not match bundle $bundle\" >&2; exit 1; }\nif [[ -n \"$ents\" && -f \"apps/ios/$ents\" ]]; then\n  for k in $(plutil -convert json -o - \"apps/ios/$ents\" | jq -r 'keys[]'); do\n    echo \"$decoded\" | plutil -extract \"Entitlements.$k\" raw -o - - >/dev/null 2>&1 \\\n      || { echo \"entitlement $k is not in the provisioning profile\" >&2; exit 1; }\n  done\nfi\necho \"signing preflight ok: $bundle\"\n","scripts/smoke.sh":"#!/usr/bin/env bash\n# Staging smoke tests against the deployed digest.\nset -euo pipefail\napi=${1:?usage: smoke.sh <api-base-url>}\ncurl -fsS \"$api/api/v1/capabilities\" | jq -e '.contract == \"v1\"' >/dev/null\ncurl -fsS -H \"Authorization: Bearer ${SMOKE_PARENT_TOKEN:?}\" \"$api/api/v1/routes\" | jq -e 'length >= 1' >/dev/null\n# Negative test: a parent cannot read a route they are not assigned to.\ncode=$(curl -s -o /dev/null -w '%{http_code}' -H \"Authorization: Bearer $SMOKE_PARENT_TOKEN\" \"$api/api/v1/routes/r-unassigned/status\")\n[[ \"$code\" == 403 || \"$code\" == 404 ]] || { echo \"cross-route read returned $code\" >&2; exit 1; }\necho \"smoke ok\"\n","scripts/upload-symbols.sh":"#!/usr/bin/env bash\n# Upload the EXACT symbols from the shipped build (drill 19). Never rebuild to get symbols.\n# Upload token comes from a protected secret; the public DSN in the app is not a secret.\nset -euo pipefail\nplatform=$1 release=$2 dist=$3\ncase \"$platform\" in\n  ios) sentry-cli debug-files upload --include-sources build/ios/RouteReady.app.dSYM.zip ;;\n  android) sentry-cli debug-files upload apps/android/app/build/outputs/mapping/release/mapping.txt ;;\n  react-native) sentry-cli sourcemaps upload --release \"$release\" --dist \"$dist\" build/js ;;\nesac\n","scripts/verify-manifest.sh":"#!/usr/bin/env bash\n# Upload/promotion guard: the artifact must be exactly the one in the manifest.\nset -euo pipefail\nartifact=$1 manifest=$2\nwant=$(jq -r '.artifact_sha256' \"$manifest\")\nhave=$(shasum -a 256 \"$artifact\" | awk '{print $1}')\n[[ \"$want\" == \"$have\" ]] || { echo \"checksum mismatch: manifest $want, artifact $have\" >&2; exit 1; }\necho \"artifact matches manifest ($have)\"\n","scripts/verify-upload-cert.sh":"#!/usr/bin/env bash\n# Block the wrong upload key BEFORE Play does (drill 3, Bug Hunt b4).\n# Compares the AAB's signing certificate with the registered UPLOAD certificate (not the app signing cert).\nset -euo pipefail\naab=$1\nactual=$(keytool -printcert -jarfile \"$aab\" | awk '/SHA256:/{print $2; exit}')\nexpected=${EXPECTED_UPLOAD_CERT_SHA256:?set EXPECTED_UPLOAD_CERT_SHA256 from Play Console > App integrity > upload key}\nif [[ \"${actual^^}\" != \"${expected^^}\" ]]; then\n  echo \"AAB is signed with SHA256 $actual but the registered upload certificate is $expected\" >&2\n  exit 1\nfi\necho \"upload certificate ok\"\n","scripts/write-manifest.sh":"#!/usr/bin/env bash\n# Write evidence/release-manifest.json (schema: evidence/release-manifest.schema.json).\n# Never write tokens, passwords, keys or personal data here (Bug Hunt b12).\nset -euo pipefail\nplatform=$1 artifact=$2 number=$3\nroot=$(git rev-parse --show-toplevel)\nmkdir -p \"$root/evidence\"\nsha256=$(shasum -a 256 \"$artifact\" | awk '{print $1}')\njq -n \\\n  --arg app \"$(jq -r --arg p \"$platform\" '.[$p].application_id' \"$root/config/apps.json\")\" \\\n  --arg platform \"$platform\" \\\n  --arg version \"$(jq -r '.marketing_version' \"$root/config/apps.json\")\" \\\n  --argjson build \"$number\" \\\n  --arg sha \"$(git rev-parse HEAD)\" \\\n  --arg run \"${GITHUB_RUN_ID:-local}\" \\\n  --arg artifact \"$(basename \"$artifact\")\" \\\n  --arg artifact_sha256 \"$sha256\" \\\n  --arg contract \"$(git log -1 --format=%h -- contracts/openapi.yaml)\" \\\n  --arg image \"${BACKEND_IMAGE_DIGEST:-unknown}\" \\\n  --slurpfile flags \"$root/config/feature-flags.json\" \\\n  '{application_id:$app, platform:$platform, marketing_version:$version, build_number:$build,\n    git_sha:$sha, workflow_run_id:$run, artifact:$artifact, artifact_sha256:$artifact_sha256,\n    backend_image_digest:$image, api_contract_revision:$contract,\n    feature_flag_defaults:$flags[0].defaults, tested_client_versions:[],\n    approvals:[], store_state:\"not_uploaded\", distribution_status:\"packaged\"}' \\\n  > \"$root/evidence/release-manifest.json\"\necho \"manifest written: $platform #$number sha256=$sha256\"\n","services/api/db/migrations/README.md":"# Database changes: expand → backfill → transition → contract\n\nEvery running server version must work against the schema during a rolling deploy (drill 14).\n\n| Step | Example | Ships with |\n|---|---|---|\n| Expand | `ALTER TABLE route_status ADD COLUMN eta_confidence numeric NULL;` | backend N |\n| Backfill | batch job fills the new column | backend N |\n| Transition | readers move to the new column; old column still written | backend N+1 |\n| Contract | drop the old column **only** when no running version reads it | backend N+2, after the overlap window |\n\nRolling back an application image does not roll back a schema. Fix forward with a new migration.\n","services/api/db/migrations/V7__expand_add_eta_confidence.sql":"-- Expand only. Nullable, no default rewrite, safe for v1 readers.\nALTER TABLE route_status ADD COLUMN IF NOT EXISTS eta_confidence numeric NULL;\n","services/api/src/main/java/org/routeready/telemetry/TelemetryIngestService.java":"package org.routeready.telemetry;\n\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\n\n/**\n * Reference: ordering, idempotency and freshness for synthetic bus telemetry (drill 12).\n * - Duplicate event_id: accepted, no effect (idempotent).\n * - Older (boot_epoch, sequence) than the current position: stored for audit, NOT applied.\n * - observed_at outside the clock-skew allowance: rejected.\n * - Readers get is_stale = true after STALE_AFTER without a fresh observation.\n */\npublic final class TelemetryIngestService {\n  static final Duration CLOCK_SKEW_ALLOWANCE = Duration.ofSeconds(30);\n  static final Duration STALE_AFTER = Duration.ofSeconds(60);\n\n  private final TelemetryRepository repo;\n  private final Clock clock;   // injected so tests use a fake clock\n\n  public TelemetryIngestService(TelemetryRepository repo, Clock clock) {\n    this.repo = repo;\n    this.clock = clock;\n  }\n\n  public Result ingest(TelemetryEvent e) {\n    Instant now = clock.instant();\n    if (e.observedAt().isAfter(now.plus(CLOCK_SKEW_ALLOWANCE))) return Result.REJECTED_FUTURE;\n\n    // Unique constraint on event_id makes this insert the idempotency check (no check-then-insert race).\n    if (!repo.insertIfAbsent(e, now)) return Result.DUPLICATE;\n\n    // Conditional update: only applies when (boot_epoch, sequence) is newer than the stored position.\n    boolean applied = repo.advancePositionIfNewer(e.busId(), e.bootEpoch(), e.sequence(), e);\n    return applied ? Result.APPLIED : Result.STORED_NOT_APPLIED;\n  }\n\n  public boolean isStale(Instant lastObservedAt) {\n    return lastObservedAt.plus(STALE_AFTER).isBefore(clock.instant());\n  }\n\n  public enum Result { APPLIED, DUPLICATE, STORED_NOT_APPLIED, REJECTED_FUTURE }\n}\n","stayready/mobile/app.config.snippet.json":"{\n  \"_comment\": \"Optional Expo/EAS experiment only (drill 20). runtimeVersion from a native fingerprint means a native dependency change produces a new runtime, so OTA updates can't reach binaries that lack the native code.\",\n  \"expo\": {\n    \"runtimeVersion\": { \"policy\": \"fingerprint\" },\n    \"updates\": { \"url\": \"https://u.expo.dev/<project-id>\" }\n  }\n}\n","stayready/services/api/app/reservations.py":"# StayReady reference (drill 17, Bug Hunt b7): tenant comes from the authenticated identity.\nfrom fastapi import APIRouter, Depends, HTTPException\n\nfrom .auth import current_user   # verifies the session token server-side\nfrom .db import db\n\nrouter = APIRouter()\n\n@router.get(\"/api/v1/reservations/current\")\ndef current_reservation(user=Depends(current_user)):\n    # X-Tenant-Id and query parameters are ignored for authorization.\n    row = db.reservations.find_one(tenant_id=user.tenant_id, guest_id=user.id)\n    if row is None:\n        raise HTTPException(status_code=404)\n    return row\n","stayready/services/api/app/service_requests.py":"# StayReady reference (drill 18, Bug Hunt b8): tenant-scoped, atomic idempotency.\n# Schema: UNIQUE (tenant_id, idempotency_key); payload_hash stored with the row.\nimport hashlib, json\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.exc import IntegrityError\n\nfrom .auth import current_user\nfrom .db import Session, ServiceRequest\nfrom .models import NewRequest\n\nrouter = APIRouter()\n\ndef payload_hash(req: NewRequest) -> str:\n    return hashlib.sha256(json.dumps(req.model_dump(exclude={\"idempotency_key\"}), sort_keys=True).encode()).hexdigest()\n\n@router.post(\"/api/v1/service-requests\", status_code=201)\ndef create(req: NewRequest, user=Depends(current_user)):\n    h = payload_hash(req)\n    with Session() as s:\n        try:\n            sr = ServiceRequest(tenant_id=user.tenant_id, guest_id=user.id,\n                                idempotency_key=req.idempotency_key, payload_hash=h,\n                                description=req.description, property_id=req.property_id)\n            s.add(sr)\n            s.commit()          # the unique index decides; no check-then-insert race\n            return sr.to_dict()\n        except IntegrityError:\n            s.rollback()\n            old = s.query(ServiceRequest).filter_by(tenant_id=user.tenant_id,\n                                                    idempotency_key=req.idempotency_key).one()\n            if old.payload_hash != h:\n                raise HTTPException(409, \"idempotency key reused with a different payload\")\n            return old.to_dict()  # replay: same result as the first, committed call\n"};
